(function(){var m=window.SITE_DATA_BY_DOMAIN||{};var d=m["moe"]||{};var a=d["algorithms"]||[];for(var i=0;i<a.length;i++){if(a[i].id=="alg-disagg-expert-parallel"){a[i]["long_html"]="<nav class=\"long-toc\"><b>本页目录</b><ol><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-disagg-expert-parallel-sec-1\">一 · 一次 decode 抖动暴露的统一 EP 缺陷</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-disagg-expert-parallel-sec-2\">二 · 解耦后的 dispatch/combine 路径</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-disagg-expert-parallel-sec-3\">三 · 预填用大 EP、解码用小 EP 的负载配方</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-disagg-expert-parallel-sec-4\">四 · 适用边界：什么该用，什么不该用</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-disagg-expert-parallel-sec-5\">五 · 故障域：专家集群停摆即全服务停摆</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-disagg-expert-parallel-sec-6\">六 · 解耦不是免费的：跨集群往返的时延账与故障面</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-disagg-expert-parallel-sec-7\">七 · 路由计算与 dispatch 打包：从注意力 GPU 出发的第一跳</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-disagg-expert-parallel-sec-8\">八 · RDMA 传输与按专家 ID 的二次路由</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-disagg-expert-parallel-sec-9\">九 · 专家集群内的分组 GEMM：接收、排序、计算</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-disagg-expert-parallel-sec-10\">十 · combine 回传与加权合并：闭合一层往返</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-disagg-expert-parallel-sec-11\">十一 · 预填与解码的 EP 度数分叉：同一机制的两套参数</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-disagg-expert-parallel-sec-12\">十二 · 故障域与重路由：跨集群往返的稳定性代价</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-disagg-expert-parallel-sec-13\">十三 · 解耦的代价：跨集群往返与故障半径</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-disagg-expert-parallel-sec-14\">十四 · 逐项拆解：$T_{\\text{layer}}$ 的四个加数各自在算什么</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-disagg-expert-parallel-sec-15\">十五 · EP 度数的优化式与 $T_{\\text{gemm}}$ 的形状</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-disagg-expert-parallel-sec-16\">十六 · 负载配方：大 EP 摊薄权重、小 EP 降跳数</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-disagg-expert-parallel-sec-17\">十七 · 序列化与跳数：小 batch decode 的时延下界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-disagg-expert-parallel-sec-18\">十八 · 容错与重路由：故障阻塞的传播路径</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-disagg-expert-parallel-sec-19\">十九 · 与统一 EP 的公式级差别</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-disagg-expert-parallel-sec-20\">二十 · 解耦收益的边界：跨集群往返何时吃掉 GEMM</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-disagg-expert-parallel-sec-21\">二十一 · 请求形态与长度分布：解耦收益的判据</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-disagg-expert-parallel-sec-22\">二十二 · 并发与批大小：小 batch decode 的收益递减区</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-disagg-expert-parallel-sec-23\">二十三 · 负载配方：预填大 EP、解码小 EP 的配置逻辑</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-disagg-expert-parallel-sec-24\">二十四 · 负载不对时的三种失效形态</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-disagg-expert-parallel-sec-25\">二十五 · 配方与调度器的接口</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-disagg-expert-parallel-sec-26\">二十六 · 工程判断：什么负载不该上这套配方</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-disagg-expert-parallel-sec-27\">二十七 · 硬件档位的三档切分与选型判据</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-disagg-expert-parallel-sec-28\">二十八 · 并行拓扑：EP 度数、分组粒度与拓扑映射</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-disagg-expert-parallel-sec-29\">二十九 · 量化方案：两侧分别定精度档</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-disagg-expert-parallel-sec-30\">三十 · KV 策略：容量、分页与跨集群可见性</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-disagg-expert-parallel-sec-31\">三十一 · 调度参数：批大小、超时与容错重路由</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-disagg-expert-parallel-sec-32\">三十二 · 逐层代价账：把 T_layer 拆成五项可归因的预算</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-disagg-expert-parallel-sec-33\">三十三 · 显存账：专家权重、分页 KV 与预留浪费的三方挤占</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-disagg-expert-parallel-sec-34\">三十四 · 带宽与通信：跳数、序列化与 RDMA 消息率的乘性叠加</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-disagg-expert-parallel-sec-35\">三十五 · 功耗与热：专家集群的利用率空洞如何变成电费</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-disagg-expert-parallel-sec-36\">三十六 · 尾延迟：故障域放大与重路由的代价传导</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-disagg-expert-parallel-sec-37\">三十七 · 规模上去以后哪里先崩：按代价项的排序判断</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-disagg-expert-parallel-sec-38\">三十八 · 精度漂移：dispatch/combine 路径上的静默误差</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-disagg-expert-parallel-sec-39\">三十九 · OOM 的三条来源与显存预留的错配</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-disagg-expert-parallel-sec-40\">四十 · 批抖动与路由不均：两个互相放大的失败模式</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-disagg-expert-parallel-sec-41\">四十一 · 尾延迟尖刺：故障阻塞与重路由的代价结构</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-disagg-expert-parallel-sec-42\">四十二 · 监控面与回滚顺序</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-disagg-expert-parallel-sec-43\">四十三 · 解耦架构的失效边界与可观测性设计</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-disagg-expert-parallel-sec-44\">四十四 · 决策的第一性原理：把 EP 选择还原成两个可测量</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-disagg-expert-parallel-sec-45\">四十五 · 决策表：六种同族形态的适用条件</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-disagg-expert-parallel-sec-46\">四十六 · 与统一 EP 的对照：解耦换来了什么、失去了什么</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-disagg-expert-parallel-sec-47\">四十七 · 与路由侧算法的对照：丢弃、选择与块稀疏的取舍</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-disagg-expert-parallel-sec-48\">四十八 · 与数值精度侧的对照：量化改变的是分母</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-disagg-expert-parallel-sec-49\">四十九 · 决策顺序与工程判断</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-disagg-expert-parallel-sec-50\">五十 · 解耦 EP 的边界判定：与统一 EP、纯 PD 分离的三角取舍</button></li></ol></nav><figure class=\"diagram\" data-fig=\"algo-flow\"><svg style=\"max-width:556px;margin:0 auto\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 556.2 352\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\"><rect x=\"58.0\" y=\"12.0\" width=\"474.2\" height=\"44.8\" rx=\"8\" fill=\"#fdf3e3\" stroke=\"#ecd9b8\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"34.4\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"38.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">1</text><text x=\"75.0\" y=\"39.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">注意力层 GPU 计算路由，把 token 及其路由权重打包为 dispa…</text><line x1=\"82.0\" y1=\"58.8\" x2=\"82.0\" y2=\"75.8\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 74.8 L 86.5 74.8 L 82.0 82.8 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"82.8\" width=\"474.2\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"105.3\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"109.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">2</text><text x=\"75.0\" y=\"110.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">dispatch 消息通过 RDMA 发往专家集群，按专家 ID 路由到对…</text><line x1=\"82.0\" y1=\"129.7\" x2=\"82.0\" y2=\"146.7\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 145.7 L 86.5 145.7 L 82.0 153.7 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"153.7\" width=\"474.2\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"176.1\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"180.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">3</text><text x=\"75.0\" y=\"181.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">专家集群内分组 GEMM 计算，结果按原 token 索引打包为 comb…</text><line x1=\"82.0\" y1=\"200.5\" x2=\"82.0\" y2=\"217.5\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 216.5 L 86.5 216.5 L 82.0 224.5 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"224.5\" width=\"474.2\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"247.0\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"251.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">4</text><text x=\"75.0\" y=\"252.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">combine 消息回传到发起 GPU，按路由权重加权合并，进入下一层</text><line x1=\"82.0\" y1=\"271.4\" x2=\"82.0\" y2=\"288.4\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 287.4 L 86.5 287.4 L 82.0 295.4 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"295.4\" width=\"474.2\" height=\"44.8\" rx=\"8\" fill=\"#e8f5ec\" stroke=\"#cde9d5\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"317.8\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"322.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">5</text><text x=\"75.0\" y=\"323.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">预填阶段用大 EP 度数摊薄权重读取，解码阶段用小 EP 度数降低通信跳数</text></svg><figcaption><b>执行流程</b> · 从输入到输出的关键步骤；每一步的复杂度与坑在正文展开。</figcaption></figure>\n<h3 id=\"alg-disagg-expert-parallel-sec-1\">一 · 一次 decode 抖动暴露的统一 EP 缺陷</h3>\n<p>某长上下文对话服务在 B200 NVL72 上跑一个大规模 MoE 模型，预填阶段吞吐正常，但线上 P99 首 token 之后的逐 token 延迟出现规律性尖刺：每隔若干步就有一批请求的 ITL 翻倍。抓取时间线后发现，尖刺并非来自注意力核或 KV 读取，而是来自每层两次 All-to-All 的等待——decode 的 batch 很小，分组 GEMM 只需极短时间，但 token 必须在所有 EP rank 之间同步往返，通信时延在层时间中占了主导。更麻烦的是，同一套 EP 度数既要服务预填（此时大 batch 需要把专家权重读取摊薄，倾向更大的 EP 度数），又要服务解码（此时小 batch 需要更少的通信跳数，倾向更小的 EP 度数），两个阶段的诉求在同一条并行拓扑上直接冲突。运维只能折中配置，结果预填侧专家权重带宽利用率上不去，解码侧又被通信拖住。这正是分离式专家并行要解决的推理问题：把专家池从注意力层解耦出去，让两个阶段各自选择 EP 度数与通信拓扑。</p>\n<p>用层时间公式可以把冲突写清楚：</p>\n<div class=\"formula\">$$T_{\\text{layer}}=T_{\\text{attn}}+\\underbrace{\\frac{S_{\\text{token}}\\,N_{\\text{token}}}{\\text{BW}_{\\text{link}}}}_{T_{\\text{dispatch}}}+T_{\\text{gemm}}+\\underbrace{\\frac{S_{\\text{out}}\\,N_{\\text{token}}}{\\text{BW}_{\\text{link}}}}_{T_{\\text{combine}}},\\quad \\text{EP}_{\\text{opt}}=\\arg\\min_{\\text{EP}}\\left(T_{\\text{gemm}}(\\text{EP})+T_{\\text{comm}}(\\text{EP})\\right)$$</div>\n<p>统一 EP 下，$\\text{EP}_{\\text{opt}}$ 只有一个解，而预填与解码的 $N_{\\text{token}}$ 相差数个量级，$T_{\\text{gemm}}$ 与 $T_{\\text{comm}}$ 的相对权重随之翻转，同一个 EP 度数不可能同时落在两条曲线的最低点。事故的本质不是某个核写得不好，而是并行拓扑被强行共享。</p>\n\n<h3 id=\"alg-disagg-expert-parallel-sec-2\">二 · 解耦后的 dispatch/combine 路径</h3>\n<p>分离式专家并行把专家池搬进独立的专家服务集群，注意力 GPU 只保留注意力层与路由计算。每层流程是：注意力 GPU 算出每个 token 的 top-k 专家与路由权重，把 token 向量与权重打包为 dispatch 消息，经 RDMA 发往专家集群；专家集群入口按专家 ID 把消息路由到持有该专家的 GPU；专家集群内部以分组 GEMM 完成专家计算，结果按原 token 索引打包为 combine 消息回传到发起 GPU；发起 GPU 按路由权重加权合并，写入残差并进入下一层。关键变化在于：注意力层与专家层之间不再共享 rank 拓扑，专家集群可以有自己的 EP 分组、自己的扩缩容边界。</p>\n<p>消息量决定了这条路径的代价。dispatch 消息量可写为：</p>\n<div class=\"formula\">$$M_{\\text{disp}} = N_{\\text{tok}} \\times k \\times (d_{\\text{model}} + w_{\\text{route}})$$</div>\n<p>其中 $N_{\\text{tok}}$ 为 token 数、$k$ 为 top-k、$d_{\\text{model}}$ 为隐藏维、$w_{\\text{route}}$ 为路由权重字节数；combine 消息量同阶。这个式子直接给出工程判断：解码阶段 $N_{\\text{tok}}$ 小，$M_{\\text{disp}}$ 小，但跨集群往返的固定跳数与序列化开销不随 $N_{\\text{tok}}$ 缩小，于是单位 token 的通信成本被放大；预填阶段 $N_{\\text{tok}}$ 大，消息量摊薄了固定开销，跨集群传输反而更容易被带宽而不是时延主导。因此同一套解耦架构在两个阶段的经济性完全不同，这也是为什么必须允许两阶段使用不同 EP 度数。</p>\n\n<h3 id=\"alg-disagg-expert-parallel-sec-3\">三 · 预填用大 EP、解码用小 EP 的负载配方</h3>\n<p>解耦之后，预填阶段可以用较大的 EP 度数：专家权重被切分到更多 GPU 上，单卡需要读取的专家权重字节数下降，分组 GEMM 的权重带宽压力被摊薄，而预填的大 batch 足以让跨集群消息量接近链路带宽上限，固定时延被摊薄。解码阶段则相反，用小 EP 度数：专家集群内部通信跳数减少，combine 回传路径更短，避免小 batch 下通信时延超过 GEMM。这个配方不是静态的，批大小按 SLO 调节，EP 度数随阶段切换，专家集群的显存预留也要按两套配置分别规划——预填配置下每卡驻留的专家更少，解码配置下每卡驻留的专家更多，切换时的权重换入换出是显存与带宽的额外代价。</p>\n<p>代价要算清楚：token 跨集群往返引入额外网络跳数与序列化开销；小 batch decode 时，这笔开销可能超过分组 GEMM 本身，抵消解耦收益。也就是说，分离式专家并行在解码侧并非无条件更快，它把“统一 EP 下的同步等待”换成了“跨集群往返的固定成本”，只有当专家层确实是独立瓶颈、且解码 batch 不至于小到让固定成本主导时，这笔交换才划算。</p>\n\n<h3 id=\"alg-disagg-expert-parallel-sec-4\">四 · 适用边界：什么该用，什么不该用</h3>\n<p>适用的一面：预填与解码通信需求差异大的自回归服务，尤其是长预填加短解码的形态；专家层已经成为独立瓶颈、注意力层与专家层需要分别扩缩容的大规模 MoE 部署；希望把专家集群当作独立资源池、按专家负载而非注意力负载扩容的场景。解耦让注意力 GPU 与专家集群可以按各自瓶颈分别优化，专家集群独立扩缩容，decode 通信跳数降低，预填与解码可使用不同 EP 度数，避免统一 EP 下解码被过度通信拖慢。</p>\n<p>不适用或收益递减的一面：规模上限受跨集群网络跳数与序列化开销约束；小 batch decode 场景收益递减，因为固定往返成本无法被 token 数摊薄；如果模型专家数少、单卡即可容纳全部专家，解耦带来的跨集群路径纯属额外开销；如果服务本身预填与解码比例稳定、统一 EP 已能同时满足两侧 SLO，解耦的运维复杂度换不来对应收益。它解决的是“统一 EP 无法同时优化两阶段”这一具体问题，不解决单卡内分组 GEMM 效率、不解决量化精度、也不解决 KV cache 容量——那些属于相邻条目的话题。</p>\n\n<h3 id=\"alg-disagg-expert-parallel-sec-5\">五 · 故障域：专家集群停摆即全服务停摆</h3>\n<p>解耦把故障域重新画了一遍，而且画得更集中。统一 EP 下某个 rank 出问题，影响的是该 rank 上的专家分片；解耦之后，所有注意力 GPU 的每一层都要经过专家集群，专家集群故障会阻塞所有注意力 GPU，缺乏重路由时整个服务停摆。这是分离式专家并行最尖锐的稳定性代价：它把专家层从“并行维度之一”提升为“全局关键路径”。工程上必须配套容错与重路由机制——专家副本、故障检测、dispatch 消息的备用路由、combine 超时后的降级路径，否则一次专家集群节点故障就是全量请求的雪崩。</p>\n<p>另一类失败模式是配置层面的：预填与解码 EP 度数配置不当会造成专家集群负载倾斜与显存预留浪费。预填配置下若某些专家被过度集中，分组 GEMM 出现长尾；解码配置下若 EP 度数过小，单卡专家权重读取成为瓶颈；两套配置切换时若显存预留没有对齐，会出现权重换入换出抖动。这些都不是算法本身能自动消解的，需要在部署配方里显式约束。</p>\n<p>把边界收束成一句工程判断：分离式专家并行值得上的信号，是专家层在 profiler 里稳定占据层时间的主要份额、且预填与解码的 EP 最优解明显分离；此时解耦换来的是两阶段各自逼近 $\\text{EP}_{\\text{opt}}$，代价是跨集群固定时延与一个必须做扎实的容错层。反过来，如果 decode batch 小到跨集群往返时延超过分组 GEMM，或者专家集群的故障重路由还没落地，那么这套架构的收益会被它自己引入的路径成本吃掉——先修容错与路由，再谈解耦。</p>\n\n\n<h3 id=\"alg-disagg-expert-parallel-sec-6\">六 · 解耦不是免费的：跨集群往返的时延账与故障面</h3>\n<p>把专家池从注意力层剥离成独立服务集群，收益来自“各按各的瓶颈优化”，代价则集中在一件事上：每个 token 在每一层都要跨一次集群边界，而且是往返两次。dispatch 消息量与 combine 消息量同阶，可写成 <span class=\"formula\">$$M_{\\text{disp}} = N_{\\text{tok}} \\times k \\times (d_{\\text{model}} + w_{\\text{route}})$$</span>，其中 <span class=\"formula\">$N_{\\text{tok}}$</span> 为 token 数、<span class=\"formula\">$k$</span> 为 top-k、<span class=\"formula\">$d_{\\text{model}}$</span> 为隐藏维、<span class=\"formula\">$w_{\\text{route}}$</span> 为路由权重字节数。这条式子说明边界条件的第一层含义：消息量随 token 数线性增长，与批大小同向；批越小，单次往返所摊薄的有效载荷越少，而固定的网络跳数与序列化开销不变。于是小 batch decode 成为该方案最脆弱的工况——跨集群往返时延可能超过分组 GEMM 的计算时间，解耦带来的通信跳数下降被额外的跨集群一跳吃掉，净收益转负。这不是配置问题，而是结构性的：只要 token 必须离开注意力 GPU 再回来，就存在一个与批大小无关的时延底噪。</p>\n<p>第二个边界是故障域。注意力 GPU 与专家集群分离部署、跨集群走 RDMA，意味着专家集群从“每张卡上的一份权重切片”变成了“所有注意力 GPU 共享的远程依赖”。专家集群故障会阻塞所有注意力 GPU，缺乏重路由时整个服务停摆。统一 EP 下某个专家所在 GPU 出问题，影响的是命中该专家的那部分 token，其余流量仍可绕行；解耦之后，专家集群是单点，容错与重路由机制不是可选项而是准入条件。工程判断上，这意味着专家集群的副本数、健康检查粒度、dispatch 消息的超时与重发策略，都要按“阻塞全部上游”的等级来设计，而不是按“局部降级”来设计。任何把专家集群当作无状态可丢弃资源的部署假设，都会在第一次节点抖动时暴露。</p>\n<p>第三个边界是 EP 度数的分段配置本身会制造新的不均衡。预填阶段用大 EP 度数摊薄专家权重读取，解码阶段用小 EP 度数降低通信跳数，两套度数对应两套专家分组与显存预留。若预填与解码的 EP 度数配置不当，会造成专家集群负载倾斜与显存预留浪费：大 EP 度数下每个专家分片小、副本多，权重读取被摊薄但显存被预留撑大；小 EP 度数下通信跳数少但单卡权重读取压力回升。更麻烦的是两阶段共用同一批专家 GPU 时，显存预留必须按两套配置的上界取，浪费是结构性的。用公式表达优化目标时，<span class=\"formula\">$$\\text{EP}_{\\text{opt}}=\\arg\\min_{\\text{EP}}\\left(T_{\\text{gemm}}(\\text{EP})+T_{\\text{comm}}(\\text{EP})\\right)$$</span> 只在单一阶段内成立；跨预填与解码两个阶段，目标函数变成两条曲线各自取极小，而资源是共享的，极小点不重合就产生倾斜。</p>\n<p>适用边界因此可以收敛成一句可操作的判断：该方案适合预填与解码通信需求差异大、专家层成为独立瓶颈的大规模 MoE 服务；规模上限受跨集群网络跳数与序列化开销约束，小 batch decode 场景收益递减。反过来说，它不解决的问题包括：不降低单 token 的专家计算量，不改变路由本身的负载不均衡，也不为小批 decode 提供时延下限保障。一个具体的失效链条是这样的：线上服务在长预填加短解码的自回归形态下运行，预填侧大 EP 度数把权重读取摊薄得很漂亮，解码侧切到小 EP 度数后批大小按 SLO 调节、实际落在很小的区间，此时每层 <span class=\"formula\">$T_{\\text{dispatch}}+T_{\\text{combine}}$</span> 由跨集群往返主导，分组 GEMM 反而成了次要项，端到端 TPOT 被通信时延钉住；与此同时专家集群一次节点故障让全部注意力 GPU 的 dispatch 消息超时，重路由缺失导致整服务停摆。这两件事共同划出了该方案的工程红线：先证明 decode 侧批大小足以摊薄跨集群往返，再证明专家集群具备阻塞级容错，否则解耦只是把通信时延从 All-to-All 换成了更贵的一跳。</p>\n<h3 id=\"alg-disagg-expert-parallel-sec-7\">七 · 路由计算与 dispatch 打包：从注意力 GPU 出发的第一跳</h3>\n<p>分离式专家并行的第一步发生在注意力层 GPU 内部，而不是专家集群。注意力层完成 softmax 之后的 top-k 路由计算，得到每个 token 的专家 ID 集合与对应路由权重。此时系统要做的不是立刻做 GEMM，而是把「计算指令」变成「可传输的消息」：把 token 的隐藏向量与路由权重一起打包为 dispatch 消息。打包的粒度决定了后续所有环节的代价结构，因此这一步的输入是 $N_{\\text{tok}}$ 个 token 的隐藏状态与 $k$ 个路由权重，输出是一批按目标专家 ID 预分组的 dispatch 消息。</p>\n<p>消息量由下式给出，它是本部分所有带宽估算的基准：</p>\n<div class=\"formula\">$$M_{\\text{disp}} = N_{\\text{tok}} \\times k \\times (d_{\\text{model}} + w_{\\text{route}})$$</div>\n<p>其中 $d_{\\text{model}}$ 是隐藏维、$w_{\\text{route}}$ 是路由权重字节数。注意 $k$ 出现在乘数里：top-k 越大，dispatch 消息量线性膨胀，而 combine 消息量同阶，因此一次层往返的有效通信量约为 $2 M_{\\text{disp}}$。这一步的系统代价是显存与带宽：打包需要在注意力 GPU 上开辟发送缓冲区，缓冲区大小与 $N_{\\text{tok}} \\times k$ 成正比；在长预填场景下 $N_{\\text{tok}}$ 很大，发送缓冲区会与分页 KV 争夺显存，因此工程上通常按 chunk 分片打包，而不是一次性攒满整个 batch。一个具体例子：当 $d_{\\text{model}}$ 为数千、$k$ 为 8 时，单 token 的 dispatch 载荷是「隐藏向量 + 8 份权重」的量级，预填 chunk 内数千 token 就会形成数 MB 级的消息批次，这一批次必须走 RDMA 而不是 PCIe，否则序列化开销会吞掉解耦收益。</p>\n\n<h3 id=\"alg-disagg-expert-parallel-sec-8\">八 · RDMA 传输与按专家 ID 的二次路由</h3>\n<p>dispatch 消息离开注意力 GPU 后进入跨集群网络。这里的关键机制是「两级路由」：第一级是注意力 GPU 决定 token 去哪个专家集群（或集群内的哪个专家分区），第二级是专家集群的入口交换机或接收端网卡按专家 ID 把消息投递到持有该专家的具体 GPU。第二级路由不能靠接收端 CPU 做软件分发，否则每个 token 都要经历一次主机内存往返，序列化开销会直接叠加到层延迟上；工程实现上依赖 RDMA 的队列对（QP）与目的地址预配置，把「专家 ID → 目标 GPU」的映射提前编译进发送描述符。</p>\n<p>这一步的代价是网络跳数与带宽。跨集群往返比集群内 All-to-All 多出至少一跳：注意力 GPU → 集群入口 → 专家 GPU。用层延迟公式拆开看：</p>\n<div class=\"formula\">$$T_{\\text{layer}}=T_{\\text{attn}}+\\underbrace{\\frac{S_{\\text{token}}\\,N_{\\text{token}}}{\\text{BW}_{\\text{link}}}}_{T_{\\text{dispatch}}}+T_{\\text{gemm}}+\\underbrace{\\frac{S_{\\text{out}}\\,N_{\\text{token}}}{\\text{BW}_{\\text{link}}}}_{T_{\\text{combine}}}$$</div>\n<p>$T_{\\text{dispatch}}$ 与 $T_{\\text{combine}}$ 都是「字节数除以链路带宽」的形式，这意味着解耦架构的通信代价并不会因为「独立集群」而消失，只是从集群内 All-to-All 的同步等待变成了跨集群的点对点流水。差别在于：统一 EP 的 All-to-All 是全局同步屏障，最慢的 rank 决定整层节奏；而分离式 dispatch 是异步消息流，注意力 GPU 可以在等待 combine 的同时继续处理下一个 micro-batch 的路由计算。代价则体现在小 batch decode 上——当 $N_{\\text{token}}$ 很小时，$T_{\\text{dispatch}}$ 的固定跳数时延（而非带宽项）占主导，跨集群往返可能超过分组 GEMM 的计算时间，这正是适用边界里「小 batch decode 收益递减」的物理来源。具体例子：decode 阶段每步只产生与批大小同阶的少量 token，若批大小按 SLO 压得很低，则每层两次跨集群往返的固定时延会直接卡住 token 间延迟（ITL）。</p>\n\n<h3 id=\"alg-disagg-expert-parallel-sec-9\">九 · 专家集群内的分组 GEMM：接收、排序、计算</h3>\n<p>消息抵达专家 GPU 后，接收端要做三件事：把来自不同注意力 GPU、不同 token 的载荷按专家 ID 归并到本地队列；按 token 在原序列中的位置建立索引表；然后以分组 GEMM 的形式对同一专家的 token 批量计算。分组 GEMM 的输入是「按专家分组的 token 矩阵」，输出是同形状的专家输出。这里的机制要点是索引表：combine 阶段必须能把结果按原 token 索引还原并加权合并，因此专家集群在计算前就要为每个 token 分配一个稳定的（源 GPU, 序列位置, top-k 槽位）三元组标识，随载荷一起传输。</p>\n<p>这一步的代价是显存与算力利用率。专家权重常驻在专家 GPU 的显存中，分组 GEMM 的算力效率取决于每个专家分到的 token 数：token 分布偏斜时，热门专家的 GEMM 成为关键路径，冷门专家的 SM 空转。这正是容量因子与令牌丢弃要处理的问题，此处不展开，只需记住：分离式架构把这种偏斜从「全局同步屏障下的木桶效应」变成了「专家集群内部的局部热点」，注意力 GPU 不再被最慢专家拖住，但专家集群自身的负载均衡仍需独立调度。预填阶段用大 EP 度数摊薄权重读取，正是因为预填的 $N_{\\text{token}}$ 大、GEMM 是带宽受限的权重读取主导，把专家切到更多 GPU 上可以让每张卡读取的权重份额变小；而 decode 阶段 $N_{\\text{token}}$ 小、GEMM 是延迟主导，切得太细反而增加通信跳数。</p>\n\n<h3 id=\"alg-disagg-expert-parallel-sec-10\">十 · combine 回传与加权合并：闭合一层往返</h3>\n<p>专家计算完成后，结果按原 token 索引打包为 combine 消息，沿 dispatch 的反向路径回传到发起 GPU。发起 GPU 收到的是同一 token 的 $k$ 份专家输出，需要按路由权重加权求和，得到该 token 在本层的最终输出，再进入下一层。合并操作的机制是「按槽位对齐」：每个 token 的 $k$ 个槽位必须与 dispatch 时记录的专家 ID 一一对应，否则权重会错配。因此 combine 消息的包头里携带槽位号，接收端用槽位号做散射-聚集（scatter-gather）而非简单拼接。</p>\n<p>代价方面，combine 消息量与 dispatch 同阶，但它多了一次「等待」语义：发起 GPU 必须等齐同一 token 的全部 $k$ 份结果才能合并，这构成了层内的一个局部屏障。与统一 EP 的全局 All-to-All 屏障相比，这个屏障的粒度是「单 token 的 k 份结果」，而非「全集群所有 rank」，因此不同 token 的 combine 可以乱序完成、流水推进。工程上的关键判断是：把合并操作放在注意力 GPU 上做，而不是在专家集群内做，原因是路由权重只存在于发起 GPU，跨集群传权重比传结果更贵。一个具体例子：当 $k$ 为 8 时，每个 token 要等 8 条 combine 消息到齐，若其中一条因网络拥塞迟到，该 token 的下一层计算就被推迟；缓解手段是把 combine 的超时与重路由绑定，迟到消息触发备用路径而非无限等待。</p>\n\n<h3 id=\"alg-disagg-expert-parallel-sec-11\">十一 · 预填与解码的 EP 度数分叉：同一机制的两套参数</h3>\n<p>上述四步在预填与解码两个阶段走的是同一条消息路径，但参数配置分叉。预填阶段 $N_{\\text{token}}$ 大，$T_{\\text{dispatch}}$ 的带宽项占主导，同时 GEMM 受权重读取带宽约束，因此选择大 EP 度数：把专家切到更多 GPU 上，单卡权重份额变小，权重读取时间被摊薄，代价是 dispatch 的跳数变多但被大消息量摊薄得不显著。解码阶段 $N_{\\text{token}}$ 小，$T_{\\text{dispatch}}$ 的固定跳数时延占主导，GEMM 受延迟约束，因此选择小 EP 度数：减少专家集群内的分组数与通信跳数，让每层往返尽快闭合。</p>\n<p>这个分叉的优化目标可以写成：</p>\n<div class=\"formula\">$$\\text{EP}_{\\text{opt}}=\\arg\\min_{\\text{EP}}\\left(T_{\\text{gemm}}(\\text{EP})+T_{\\text{comm}}(\\text{EP})\\right)$$</div>\n<p>预填时 $T_{\\text{gemm}}$ 随 EP 增大而下降的斜率陡于 $T_{\\text{comm}}$ 上升的斜率，解码时相反。系统代价体现在专家集群的显存预留上：两套 EP 度数意味着专家集群要按两种切分方式准备权重布局，若在同一批 GPU 上动态切换，需要预留切换窗口或双份权重副本，这会吃掉本可用于 KV cache 的显存。工程判断是：预填与解码若在同一专家集群上分时复用，切换成本必须计入容量规划；若分成两个专家池，则扩缩容独立性更好但集群利用率下降。配置不当的失败模式很直接：预填用小 EP 度数会导致权重读取成为瓶颈，解码用大 EP 度数会让通信跳数压过 GEMM，两者都会造成专家集群负载倾斜与显存预留浪费。</p>\n\n<h3 id=\"alg-disagg-expert-parallel-sec-12\">十二 · 故障域与重路由：跨集群往返的稳定性代价</h3>\n<p>分离式架构把专家池变成独立服务集群，也把故障域从「单 GPU 掉队」升级为「集群级阻塞」：专家集群故障会阻塞所有注意力 GPU，因为每一层都必须经过它。机制上需要两条防线：其一是 dispatch 侧的备用路径，当目标专家 GPU 不可达时，把消息重路由到持有同一专家副本的另一张卡（若有冗余副本）或降级到容量因子内的替代专家；其二是 combine 侧的超时与部分合并，允许在缺失部分槽位时用零权重占位继续推进，避免整个 batch 停摆。</p>\n<p>这一步的代价是延迟抖动与显存冗余。重路由本身要查表并改写目的地址，增加了 dispatch 的序列化开销；冗余专家副本则直接占用专家集群显存。定性地说，容错机制的复杂度与专家集群规模正相关：集群越大，单点故障概率越高，重路由表也越大。具体例子：当一个专家分区整体失联时，所有路由到该分区的 token 必须在 dispatch 阶段被改写目标，若重路由表未预热，这批 token 会经历一次额外的控制面往返，其延迟远高于正常数据面跳数。因此工程上把重路由表做成数据面可查的预编译结构，而不是故障时才去查询调度器。这条防线的存在，正是分离式专家并行在「解耦收益」与「跨集群往返代价」之间必须付出的稳定性成本。</p>\n\n<h3 id=\"alg-disagg-expert-parallel-sec-13\">十三 · 解耦的代价：跨集群往返与故障半径</h3>\n<p>把专家池搬出注意力 GPU 之后，每层的时间账要重算。设 token 数 $N_{\\text{tok}}$、top-k 为 $k$、隐藏维 $d_{\\text{model}}$、路由权重字节 $w_{\\text{route}}$，则单次 dispatch 的消息量为 $M_{\\text{disp}} = N_{\\text{tok}} \\times k \\times (d_{\\text{model}} + w_{\\text{route}})$，combine 同阶；再叠加跨集群 RDMA 的一次序列化与反序列化，每层实际开销是 $T_{\\text{dispatch}}+T_{\\text{combine}}$ 加上两端打包/解包的固定时延，而非单纯的链路传输时间。这条固定项与 batch 无关，因此在小 batch decode 时被放大：当 $N_{\\text{tok}}$ 很小，分组 GEMM 的有效算力利用率本就低，跨集群往返的跳数与序列化开销可能直接超过 GEMM 本体，解耦收益归零。判断阈值应写成“往返时延 < 该层 GEMM 时间”的显式约束，而不是靠经验拍板。</p>\n<p>失效条件不止于性能。专家集群是全局共享资源，任一专家 GPU 故障都会阻塞所有发起 dispatch 的注意力 GPU——注意力层此时既不能本地兜底（权重不在本地），也无法跳过该层，只能等待重路由。因此系统必须内置专家副本、故障检测与 token 重发路径，且重路由本身要消耗额外一跳网络与一次重复的 dispatch 消息量，等于把容错成本计入稳态延迟预算。缺乏重路由时，单点故障即服务停摆，这是解耦架构相对统一 EP 最实质的稳定性退让。</p>\n<p>配置层面还有一处易被忽略的耦合：预填用大 EP 度数摊薄权重读取、解码用小 EP 度数降低跳数，两套度数共用同一专家集群的显存预留。若按预填峰值静态划分专家分片，解码时段大量分片空置，显存浪费；若按解码规模划分，预填又摊不薄权重读取。EP 度数需按请求形态的时间占比动态调整，并配合专家集群的独立扩缩容，否则负载倾斜会把解耦带来的调度自由度吃掉。规模上限因此由跨集群网络跳数与序列化开销共同约束，而非单纯受限于集群 GPU 数量。</p>\n<table class=\"mini\"><thead><tr><th>阶段</th><th>主导代价</th><th>失效信号</th></tr></thead><tbody><tr><td>预填</td><td>权重读取带宽，大 EP 摊薄</td><td>专家分片显存预留过量</td></tr><tr><td>解码</td><td>跨集群往返时延与序列化</td><td>往返时延超过分组 GEMM</td></tr><tr><td>故障</td><td>重路由额外一跳与重发</td><td>无副本时全服务阻塞</td></tr></tbody></table>\n<h3 id=\"alg-disagg-expert-parallel-sec-14\">十四 · 逐项拆解：$T_{\\text{layer}}$ 的四个加数各自在算什么</h3>\n<p>把一层 MoE 的时间写成四个可分离的项，价值不在公式本身，而在于每一项都对应一个可以独立调节的旋钮。$T_{\\text{attn}}$ 是注意力层在发起 GPU 上的本地计算，它不随 EP 度数变化——这是解耦架构最关键的收益来源：注意力侧的时间被从专家侧的通信中摘出来了。$T_{\\text{dispatch}}$ 与 $T_{\\text{combine}}$ 是两次跨集群传输，分母都是 $\\text{BW}_{\\text{link}}$，分子是消息字节数。$T_{\\text{gemm}}$ 是专家集群内的分组 GEMM 时间，它随 EP 度数增大而减小（权重读取被摊薄），但随专家集群内部通信跳数增大而增大。</p>\n<p>推导的关键一步是把消息字节数写成可计算的量。dispatch 消息量 $M_{\\text{disp}} = N_{\\text{tok}} \\times k \\times (d_{\\text{model}} + w_{\\text{route}})$，其中 $N_{\\text{tok}}$ 是待发 token 数、$k$ 是 top-k、$d_{\\text{model}}$ 是隐藏维、$w_{\\text{route}}$ 是路由权重字节数。注意括号里的两项量级悬殊：在 NVFP4 或 FP8 激活下，$d_{\\text{model}}$ 对应的载荷是主导项，$w_{\\text{route}}$ 只是每 token 每专家的一个标量权重，它的存在是为了让 combine 侧能按权重加权合并，而不是为了传输效率。因此 $T_{\\text{dispatch}} \\approx N_{\\text{tok}} \\cdot k \\cdot d_{\\text{model}} \\cdot b_{\\text{act}} / \\text{BW}_{\\text{link}}$，其中 $b_{\\text{act}}$ 是每元素字节数。combine 消息量同阶——因为回传的同样是 $k$ 份专家输出，只是不再需要携带路由权重（权重已在发起侧保留）。</p>\n<p>这个同阶关系带来一个容易被忽略的工程判断：dispatch 与 combine 的时延大致对称，所以任何只优化单向链路的做法收益上限只有一半。真正有效的是把两次传输都压到同一个低跳数拓扑上，或者把 combine 与下一层的 dispatch 做流水重叠。</p>\n<p>具体例子：一个 $d_{\\text{model}}$ 较大、$k$ 取常见值的 MoE 层，在 decode 阶段 $N_{\\text{tok}}$ 等于批内 token 数，量级很小；此时 $M_{\\text{disp}}$ 的绝对字节数不大，但 $\\text{BW}_{\\text{link}}$ 的有效值受限于小消息的序列化开销与 RDMA 建链成本，实际可达带宽远低于线速。这就是为什么小 batch decode 下通信时延会超过 GEMM——不是带宽不够，是消息太小、固定开销占比过高。</p>\n\n<h3 id=\"alg-disagg-expert-parallel-sec-15\">十五 · EP 度数的优化式与 $T_{\\text{gemm}}$ 的形状</h3>\n<p>$\\text{EP}_{\\text{opt}}=\\arg\\min_{\\text{EP}}\\left(T_{\\text{gemm}}(\\text{EP})+T_{\\text{comm}}(\\text{EP})\\right)$ 是一个一维搜索，但要真正求解，必须知道两项随 EP 的变化方向相反且非线性。$T_{\\text{gemm}}(\\text{EP})$ 的下降来自权重读取摊薄：单卡需要读取的专家权重字节数约为 $W_{\\text{total}}/\\text{EP}$（在专家均匀分布假设下），而激活读取量不随 EP 变化。因此当权重读取主导 GEMM 时间时，$T_{\\text{gemm}} \\propto 1/\\text{EP}$，边际收益递减。</p>\n<p>$T_{\\text{comm}}(\\text{EP})$ 的上升有两个来源。其一是专家集群内部的 All-to-All 跳数随 EP 增大而对数或线性增长，取决于拓扑；其二是 dispatch 消息在更大集群内需要经过更多交换机层级，序列化与排队开销上升。把两者相加，最优点通常落在 $T_{\\text{gemm}}$ 的边际下降等于 $T_{\\text{comm}}$ 的边际上升处，即</p>\n<div class=\"formula\">$$\\frac{\\partial T_{\\text{gemm}}}{\\partial \\text{EP}} + \\frac{\\partial T_{\\text{comm}}}{\\partial \\text{EP}} = 0$$</div>\n<p>这个条件的工程含义是：当专家权重已经小到单卡可容纳、权重读取不再是瓶颈时，继续增大 EP 只增加通信成本，最优点向左移动。这正是预填与解码需要不同 EP 度数的数学根据——预填阶段 $N_{\\text{tok}}$ 大，GEMM 是计算主导且权重读取占比高，最优点偏大 EP；解码阶段 $N_{\\text{tok}}$ 小，GEMM 时间被权重读取主导但绝对量小，通信固定开销占比高，最优点偏小 EP。</p>\n<p>伪代码落到可实现，核心是一个按阶段选择 EP 度数的调度器：</p>\n<ul>\n<li>输入：当前批次阶段（prefill / decode）、批内 token 数 $N_{\\text{tok}}$、可用专家集群分组列表、各分组的实测 $\\text{BW}_{\\text{link}}$ 与跳数。</li>\n<li>对每个候选 EP 度数，估算 $T_{\\text{gemm}}$：以 $W_{\\text{total}}/\\text{EP}$ 为权重读取量、以 $N_{\\text{tok}} \\cdot k$ 为激活 token 数，套用分组 GEMM 的 roofline 估算，取计算与带宽两者的较大者。</li>\n<li>估算 $T_{\\text{comm}}$：用 $M_{\\text{disp}}/\\text{BW}_{\\text{link}}$ 加跳数乘以单跳固定时延，combine 同法，两者相加。</li>\n<li>取 $\\arg\\min$ 作为本批次的 EP 度数，把 dispatch 消息按专家 ID 路由到对应分组。</li>\n<li>若候选集合为空或估算超出 SLO 预算，退回到固定小 EP 度数并标记该批次为降级服务。</li>\n</ul>\n<p>代价面：这个调度器每批次做一次一维搜索，开销可忽略；真正的代价是 EP 度数切换时的专家集群重分组——已驻留的专家权重需要重新分布，切换期间该集群不可用。因此实现上通常把预填与解码绑定到两组固定的专家集群分组，而不是逐批次动态切换，用静态分组换取无重分组开销。</p>\n\n<h3 id=\"alg-disagg-expert-parallel-sec-16\">十六 · 负载配方：大 EP 摊薄权重、小 EP 降跳数</h3>\n<p>预填阶段用大 EP 度数，理由可以量化。预填时 $N_{\\text{tok}}$ 大，分组 GEMM 的激活读取量 $N_{\\text{tok}} \\cdot k \\cdot d_{\\text{model}} \\cdot b_{\\text{act}}$ 随 token 数线性增长，而权重读取量固定为 $W_{\\text{total}}/\\text{EP}$。当激活读取量超过权重读取量时，GEMM 进入计算主导区，此时增大 EP 对 $T_{\\text{gemm}}$ 的边际收益变小；但在激活读取量尚未超过权重读取量的区间，增大 EP 直接摊薄权重读取，收益显著。预填的大 batch 恰好落在这个区间的前半段，所以大 EP 是合算的。</p>\n<p>解码阶段用小 EP 度数，理由在跳数。decode 时 $N_{\\text{tok}}$ 等于批内并发 token 数，$M_{\\text{disp}}$ 很小，$T_{\\text{dispatch}}$ 被固定开销主导而非带宽主导。此时 EP 度数每增加一档，dispatch 消息要多经过一层集群内转发，跳数增加带来的时延增量是固定的，而 $T_{\\text{gemm}}$ 的下降已经很小。于是 $\\partial T_{\\text{comm}}/\\partial \\text{EP}$ 压过 $\\partial T_{\\text{gemm}}/\\partial \\text{EP}$，最优点向小 EP 移动。</p>\n<p>具体例子：长预填加短解码的自回归服务，预填批次 token 数远大于解码批次，两者若共用同一 EP 度数，则解码侧被迫承担为预填优化的高跳数拓扑，decode 的每 token 时延被通信拖长。分离部署后，预填走大 EP 分组、解码走小 EP 分组，两组的专家权重各自驻留，互不干扰。代价是显存：两组专家集群各自持有完整或部分专家权重，总显存占用高于统一 EP，这是用显存换时延的典型交换。</p>\n<p>批大小按 SLO 调节，材料未给出具体批大小与 SLO 数值，因此实现上应把批大小作为 EP 选择的输入变量而非固定常量：批大小上升使 $N_{\\text{tok}}$ 上升，最优点 EP 随之上移，调度器应能感知这一漂移。</p>\n\n<h3 id=\"alg-disagg-expert-parallel-sec-17\">十七 · 序列化与跳数：小 batch decode 的时延下界</h3>\n<p>跨集群往返引入的额外时延由两部分构成：网络跳数与序列化开销。跳数部分可写成 $h \\cdot \\tau_{\\text{hop}}$，其中 $h$ 是 dispatch 或 combine 路径上的转发层数，$\\tau_{\\text{hop}}$ 是单跳固定时延；序列化部分与消息大小和每字节处理成本相关。小 batch decode 下 $M_{\\text{disp}}$ 小，序列化部分不大，但 $\\tau_{\\text{hop}}$ 是固定的，无法通过减小消息来摊薄。</p>\n<p>于是 decode 的通信时延下界近似为 $2 \\cdot h \\cdot \\tau_{\\text{hop}}$（往返各一次），它与 $T_{\\text{gemm}}$ 的比较决定了分离式专家并行在 decode 上是否划算。当 $2 h \\tau_{\\text{hop}} &gt; T_{\\text{gemm}}$ 时，解耦收益被抵消——这正是失败模式中“小 batch decode 下跨集群往返时延可能超过分组 GEMM”的定量表述。</p>\n<p>伪代码层面的应对是把 combine 与下一层 dispatch 做流水：在专家集群计算完成、combine 消息尚未全部回传时，发起 GPU 已可以对已到达的部分 token 启动下一层注意力计算，只要下一层的路由不依赖未到达的 token。这要求 combine 消息按原 token 索引分片回传，而不是整批同步。实现上给每个 token 维护一个到达计数器，达到阈值即触发下一层，阈值由 SLO 与显存预算共同决定。</p>\n<p>代价面：流水化提高了发起 GPU 的显存占用（需要同时持有当前层与下一层的中间激活），并且增加了调度复杂度。收益是把往返时延从关键路径上部分移除，使 $2 h \\tau_{\\text{hop}}$ 与 $T_{\\text{gemm}}$ 重叠而非串行相加。</p>\n\n<h3 id=\"alg-disagg-expert-parallel-sec-18\">十八 · 容错与重路由：故障阻塞的传播路径</h3>\n<p>专家集群故障会阻塞所有注意力 GPU，这个传播路径值得拆开看。发起 GPU 在 dispatch 后进入等待 combine 的状态，若专家集群某个分组失效，该分组承载的专家对应的 token 永远等不到 combine 消息，发起 GPU 的该层无法推进，进而整个批次停滞。由于所有注意力 GPU 共享同一专家集群，故障是全局性的，而非局部降级。</p>\n<p>重路由机制的核心是把“专家 ID 到 GPU”的映射做成可失效的间接层。dispatch 消息携带专家 ID 而非目标 GPU 地址，由专家集群入口的转发层解析当前映射；某分组失效时，转发层把该专家 ID 重映射到持有该专家副本的另一分组，或退回给发起 GPU 由其在本地做降级计算。伪代码上，发起侧维护一个超时计时器，超时未收到 combine 即触发重路由请求，重路由请求本身走控制面而非数据面，避免与数据流量争抢带宽。</p>\n<p>代价面：重路由需要专家副本，副本意味着额外的显存占用与权重同步开销；若不做副本而做退回本地计算，则发起 GPU 需要临时加载该专家权重，加载时延可能超过重路由收益。工程判断是：对时延敏感的 decode 路径做副本重路由，对吞吐敏感的 prefill 路径做退回本地计算，因为 prefill 的批次大、单 token 时延容忍度高。</p>\n<p>另一个稳定性技巧是把 EP 度数配置与专家集群负载绑定校验：预填与解码 EP 度数配置不当会造成专家集群负载倾斜与显存预留浪费。校验方式是在调度器内维护每个分组的实测 token 到达率与显存水位，当某分组到达率持续偏离均值时，触发 EP 度数重选或 token 重分布，而不是等到队列积压才反应。</p>\n\n<h3 id=\"alg-disagg-expert-parallel-sec-19\">十九 · 与统一 EP 的公式级差别</h3>\n<p>统一 EP 下，$T_{\\text{comm}}$ 与 $T_{\\text{gemm}}$ 被绑定在同一个 EP 度数上，优化式退化为一维搜索但搜索空间被锁死：预填与解码共享同一个 $\\text{EP}$，$\\arg\\min$ 只能取一个折中点，必然有一侧偏离其自身最优。分离式专家并行把这个约束解开，允许预填与解码各自持有 $\\text{EP}_{\\text{prefill}}$ 与 $\\text{EP}_{\\text{decode}}$，代价是两次搜索各自独立、两组专家集群各自驻留权重。</p>\n<p>公式级差别体现在 $T_{\\text{comm}}$ 的构成上：统一 EP 的通信发生在同一集群内的 All-to-All，跳数由集群拓扑决定；分离式的通信跨集群，跳数多一层入口转发，但换来的是注意力侧 $T_{\\text{attn}}$ 与专家侧 $T_{\\text{gemm}}$ 的独立扩缩容。当专家层成为独立瓶颈时，这个交换是正向的；当跨集群跳数与序列化开销压过 GEMM 时，交换是负向的，适用边界由此划定。</p>\n<p>工程判断落在具体机制上：把 $\\text{EP}_{\\text{opt}}$ 的搜索做成按阶段、按批大小、按实测带宽的在线估算，而不是离线定死一个度数；把 combine 与下一层 dispatch 做流水以隐藏往返时延；把专家 ID 到 GPU 的映射做成可失效间接层以支撑重路由。这三件事共同决定了分离式专家并行在给定集群上能否兑现公式承诺的收益。</p>\n\n<h3 id=\"alg-disagg-expert-parallel-sec-20\">二十 · 解耦收益的边界：跨集群往返何时吃掉 GEMM</h3>\n<p>把 $T_{\\text{comm}}$ 展开成可实现的形式，才能看清解耦在什么条件下失效。dispatch 消息量按 $M_{\\text{disp}} = N_{\\text{tok}} \\times k \\times (d_{\\text{model}} + w_{\\text{route}})$ 计，combine 同阶，于是每层跨集群往返的字节数约为 $2M_{\\text{disp}}$，折算时延为 $T_{\\text{comm}} \\approx 2M_{\\text{disp}}/\\text{BW}_{\\text{link}} + 2h\\,t_{\\text{hop}} + T_{\\text{ser}}$，其中 $h$ 为跨集群跳数、$t_{\\text{hop}}$ 为单跳时延、$T_{\\text{ser}}$ 为消息序列化与反序列化开销。判据因此很直接：解耦有净收益当且仅当 $T_{\\text{comm}} &lt; T_{\\text{gemm}}^{\\text{unified}} - T_{\\text{gemm}}^{\\text{decoupled}}$，即省下的专家权重读取时间必须大于新增的往返代价。预填阶段 $N_{\\text{tok}}$ 大、GEMM 计算占主导，大 EP 度数摊薄权重读取的收益稳稳压过往返开销；解码阶段 $N_{\\text{tok}}$ 小，$T_{\\text{gemm}}$ 随 batch 线性缩小，而 $2h\\,t_{\\text{hop}} + T_{\\text{ser}}$ 是几乎不随 batch 变化的固定项，二者必然在某个批大小处交叉。</p>\n<p>伪代码层面，这个交叉点必须在调度器里被显式判断，而不是靠经验配置。注意力 GPU 侧每层执行：计算路由得到 top-k 专家 ID 与权重，按专家 ID 排序打包 dispatch 消息，经 RDMA 发往专家集群对应 GPU；专家集群侧按专家分组做 GEMM，结果按原 token 索引重排为 combine 消息回传；发起 GPU 按路由权重加权合并后进入下一层。关键的一步是在 dispatch 前插入分支：若当前批的 token 数低于阈值且跨集群跳数超过预算，则回退到本地或同机架的小 EP 路径，避免为少量 token 支付固定往返时延。这个阈值不是常数，它随 $\\text{BW}_{\\text{link}}$、$h$、$T_{\\text{ser}}$ 变化，需按部署拓扑实测标定。</p>\n<table class=\"mini\"><thead><tr><th>阶段</th><th>主导项</th><th>EP 度数取向</th><th>失效条件</th></tr></thead><tbody><tr><td>预填</td><td>$T_{\\text{gemm}}$（权重读取摊薄）</td><td>大 EP</td><td>专家集群显存预留不足导致排队</td></tr><tr><td>解码（大 batch）</td><td>$T_{\\text{comm}}$ 与 $T_{\\text{gemm}}$ 同阶</td><td>中等 EP</td><td>EP 配置不当引发专家负载倾斜</td></tr><tr><td>解码（小 batch）</td><td>$2h\\,t_{\\text{hop}} + T_{\\text{ser}}$</td><td>小 EP 或回退</td><td>往返时延超过分组 GEMM，收益转负</td></tr></tbody></table>\n<p>系统代价还有一条不对称的耦合：专家集群是共享资源，其故障会阻塞所有注意力 GPU，缺乏重路由时整个服务停摆。因此容错设计不能只做副本，还要在 dispatch 消息里携带超时与备用专家映射，使发起 GPU 能在专家集群无响应时把 token 重定向到本地影子专家或另一组专家集群，代价是显存预留翻倍与路由表维护开销。工程判断落在两处：一是把跨集群跳数与序列化开销压到与单层 GEMM 同阶以下，否则解耦只在大批预填时成立；二是把 EP 度数做成随批大小与 SLO 动态切换的运行时参数，而不是部署期固定值，否则预填与解码的差异化配置反而制造负载倾斜与显存浪费。</p>\n<h3 id=\"alg-disagg-expert-parallel-sec-21\">二十一 · 请求形态与长度分布：解耦收益的判据</h3>\n<p>分离式专家并行把专家池从注意力层剥离成独立服务集群，收益的前提是“预填与解码对通信模式的需求真的不同”。落到请求形态上，这条前提等价于：输入侧长、输出侧短，且长预填占据主要计算量。长预填时，注意力 GPU 每层产生的 token 数量大，dispatch 消息可以摊薄跨集群往返的固定开销（序列化、RDMA 建链、跳数时延），专家集群内分组 GEMM 的权重读取被大量 token 分摊，大 EP 度数把专家权重切得更细，单卡权重读取量下降，GEMM 时间随之下降。短解码时，每步只有每序列一个 token，dispatch 消息量骤减，跨集群往返的固定开销无法摊薄，此时应收缩 EP 度数、减少通信跳数，让专家集群内的分组 GEMM 尽量在少数几跳内完成。</p>\n<p>用消息量公式判断形态是否匹配：</p>\n<div class=\"formula\">$$M_{\\text{disp}} = N_{\\text{tok}} \\times k \\times (d_{\\text{model}} + w_{\\text{route}})$$</div>\n<p>预填阶段 $N_{\\text{tok}}$ 是整段 prompt 的 token 数，量级由输入长度决定；解码阶段 $N_{\\text{tok}}$ 等于当前批内活跃序列数。若服务以短输入短输出为主（例如交互式补全、分类打标），预填与解码的消息量同阶，解耦带来的“分别选 EP 度数”的空间被压缩，跨集群往返反而成为纯开销。反之，长文档摘要、代码库级检索增强、多轮长上下文问答这类形态，输入长度远大于输出长度，预填的 GEMM 主导时间、解码的通信主导时间，两条曲线分离，才是这套部署配方的目标负载。</p>\n<p>长度分布的尾部同样关键。若长度分布方差大，预填批次内 token 数不均，专家集群收到的 dispatch 消息在时间上呈脉冲状：长请求集中到达时专家集群被打满，短请求间隙时专家集群空转，而注意力 GPU 仍在按自己的节奏发消息。工程上需要按长度分桶调度，把长预填请求聚成批以维持专家集群的利用率，同时避免短解码请求被长预填请求的排队延迟拖累。代价体现在尾延迟：专家集群的排队时间直接叠加到所有注意力 GPU 的关键路径上，因为 combine 消息不回传，下一层就无法开始。</p>\n\n<h3 id=\"alg-disagg-expert-parallel-sec-22\">二十二 · 并发与批大小：小 batch decode 的收益递减区</h3>\n<p>解码阶段的并发量决定解耦是否划算。设批内活跃序列数为 $B$，每步 dispatch 消息量为 $B \\times k \\times (d_{\\text{model}} + w_{\\text{route}})$，而跨集群往返的固定时延（跳数、序列化、协议处理）与 $B$ 无关。于是单步解码时间可近似写成固定项加可摊薄项：</p>\n<div class=\"formula\">$$T_{\\text{step}} \\approx T_{\\text{fixed}} + \\frac{B \\cdot k \\cdot (d_{\\text{model}} + w_{\\text{route}})}{\\text{BW}_{\\text{link}}} + T_{\\text{gemm}}(B)$$</div>\n<p>当 $B$ 小，$T_{\\text{fixed}}$ 占主导，跨集群往返时延可能超过分组 GEMM 的计算时间，解耦收益被抵消——这正是材料中标注的失败模式。此时正确做法不是硬撑分离部署，而是收缩 EP 度数、把专家集群的通信拓扑压到更少跳数，或者把解码请求聚批到足够大使固定项被摊薄。批大小按 SLO 调节，材料未给出具体批大小与 SLO 数值，因此配方只能给出方向：解码批越大，解耦越接近盈亏平衡点；批越小，越应向统一 EP 或更小 EP 度数退化。</p>\n<p>并发还影响专家集群的负载倾斜。专家选择路由天然不均衡，热门专家收到的 token 多。大 batch 时这种倾斜被统计平均稀释，分组 GEMM 的各组规模相对均匀；小 batch 时倾斜被放大，少数专家所在 GPU 成为瓶颈，其余 GPU 空等，combine 消息被最慢的那一组拖住。预填与解码 EP 度数配置不当会进一步加剧这一点：预填用大 EP 度数把专家切得很细，解码若沿用同一度数，小 batch 下每个专家 GPU 分到的 token 太少，GEMM 效率低而通信跳数多，形成“显存预留浪费 + 负载倾斜”的双重代价。</p>\n<p>具体例子：一个 8 卡注意力集群对接 32 卡专家集群，预填时每批 4096 token、top-k=2，dispatch 消息量按公式为 $4096 \\times 2 \\times (d_{\\text{model}} + w_{\\text{route}})$，摊到 32 卡上每卡接收量可观，分组 GEMM 能跑满；切到解码，批内 16 个序列，每步消息量降为 $16 \\times 2 \\times (d_{\\text{model}} + w_{\\text{route}})$，跨集群往返固定时延不变，单步时间被固定项吃掉，此时应把解码的 EP 度数降到 8 甚至 4，减少跳数与序列化次数。</p>\n\n<h3 id=\"alg-disagg-expert-parallel-sec-23\">二十三 · 负载配方：预填大 EP、解码小 EP 的配置逻辑</h3>\n<p>配方由两个独立旋钮构成：预填阶段的 EP 度数和解码阶段的 EP 度数。预填阶段目标是摊薄专家权重读取，因此取大 EP 度数，把专家权重切分到更多 GPU，单卡权重读取字节数下降，分组 GEMM 的算术强度上升；代价是 dispatch 与 combine 的跳数增加，但预填 token 多，通信量可摊薄，跳数时延被 GEMM 时间掩盖。解码阶段目标是降低通信跳数，因此取小 EP 度数，专家权重集中在少数 GPU 上，单卡权重读取量上升，但解码每步 token 少、GEMM 时间短，通信时延成为主要矛盾，减少跳数比摊薄权重更重要。</p>\n<p>两个度数之间的切换点由公式给出：</p>\n<div class=\"formula\">$$\\text{EP}_{\\text{opt}}=\\arg\\min_{\\text{EP}}\\left(T_{\\text{gemm}}(\\text{EP})+T_{\\text{comm}}(\\text{EP})\\right)$$</div>\n<p>预填时 $T_{\\text{gemm}}$ 随 EP 增大而下降的斜率陡，$T_{\\text{comm}}$ 随 EP 增大而上升但被大 token 数摊薄，最优点偏大；解码时 $T_{\\text{gemm}}$ 本身很小，$T_{\\text{comm}}$ 的固定项不随 token 数缩小，最优点偏小。工程上不必对每个请求单独求解，而是按请求所处阶段（预填队列 / 解码队列）套用两套预设度数，并在专家集群侧按度数分区：大 EP 分区与小 EP 分区各自持有专家权重的不同切分，切换时不做权重重分布，只做请求路由。</p>\n<p>代价落在显存上：两套 EP 度数意味着专家集群要同时保留两种切分下的权重副本或至少保留可快速重组的布局，显存预留按最大度数配置，小度数分区实际利用率低，形成预留浪费。这是配方必须接受的固定成本，换来的收益是预填不被解码的通信需求拖慢、解码不被预填的权重读取需求拖慢。若服务负载单一（只有长预填或只有短解码），这套双度数配方退化为单度数，解耦的主要收益随之消失。</p>\n\n<h3 id=\"alg-disagg-expert-parallel-sec-24\">二十四 · 负载不对时的三种失效形态</h3>\n<p>第一种是短输入短输出的交互式负载。预填 token 少，dispatch 消息量小，专家集群内分组 GEMM 的权重读取无法被摊薄，大 EP 度数下每卡分到的 token 不足以填满 GEMM 流水；解码侧批小，跨集群往返固定时延占主导。两侧同时落在收益递减区，解耦只增加了一跳网络和一次序列化，端到端延迟高于统一 EP。判断信号是：预填批的 token 数低于某个使 GEMM 时间超过通信固定项的阈值，且解码批内序列数长期偏低。</p>\n<p>第二种是长度分布极度不均的混合负载。少量超长预填请求与大量短解码请求共享同一专家集群，超长预填把专家集群打满，短解码请求的 combine 消息排在队列后面，尾延迟被拉长。更糟的是专家集群故障会阻塞所有注意力 GPU：注意力层发完 dispatch 后必须等 combine 才能进下一层，专家集群任一组 GEMM 卡住或所在 GPU 失联，所有注意力 GPU 同步停摆，缺乏重路由时整个服务停摆。这是解耦把故障域从单卡扩大到跨集群的直接代价，负载越不均，排队与故障的耦合越强。</p>\n<p>第三种是 EP 度数配置与负载错配。预填配了小 EP 度数，专家权重读取摊不薄，预填 GEMM 成为瓶颈；解码配了大 EP 度数，跳数多、每卡 token 少，GEMM 效率低且通信时延高。两种错配都表现为专家集群负载倾斜：热门专家所在 GPU 排队，冷门专家 GPU 空转，而注意力 GPU 侧看到的是 combine 消息迟迟不回。显存侧则表现为按大度数预留、按小度数使用，预留浪费与倾斜同时存在。工程判断是：先用消息量公式估算两阶段的 $N_{\\text{tok}}$ 量级，若预填与解码的消息量差距不足一个数量级，双度数配方的收益不足以覆盖跨集群固定开销，应退回统一 EP 或改用其他解耦维度。</p>\n\n<h3 id=\"alg-disagg-expert-parallel-sec-25\">二十五 · 配方与调度器的接口</h3>\n<p>负载配方要落地，调度器必须知道每个请求处于哪个阶段、批内 token 数多少、目标 EP 度数是什么。连续批处理下，预填队列与解码队列分开维护，预填批按 token 总数聚批以摊薄通信，解码批按序列数聚批以摊薄固定时延；两批分别打上 EP 度数标签，dispatch 消息按标签路由到专家集群对应分区。伪代码思路：</p>\n<div class=\"formula\">$$\\text{for each batch: } \\text{EP} = \\begin{cases} \\text{EP}_{\\text{large}} &amp; \\text{if phase}=\\text{prefill} \\\\ \\text{EP}_{\\text{small}} &amp; \\text{if phase}=\\text{decode} \\end{cases}$$</div>\n<p>调度器的代价是状态复杂度：同一注意力 GPU 可能同时持有预填批与解码批，两批的 dispatch 消息走不同分区、不同跳数，combine 消息回来的顺序与发出顺序不一致，需要按 token 索引重排。这要求 dispatch 与 combine 消息都携带原 token 索引与路由权重，合并时按索引对齐。索引对齐的开销在批大时被摊薄，在批小时成为额外固定成本，与跨集群往返时延叠加，进一步压缩小 batch 解码的收益。</p>\n<p>容量规划上，专家集群的规模应按预填峰值配置而非解码峰值：预填决定 GEMM 吞吐与权重读取带宽，解码只决定通信跳数与固定时延。若按解码峰值配置专家集群，预填高峰时专家集群成为瓶颈，注意力 GPU 排队等 combine；若按预填峰值配置，解码低谷时专家集群利用率低，但固定时延不受集群规模影响，解码侧不会因集群缩小而变快。这是解耦部署的容量不对称：算力按预填配，拓扑按解码调。</p>\n\n<h3 id=\"alg-disagg-expert-parallel-sec-26\">二十六 · 工程判断：什么负载不该上这套配方</h3>\n<p>判断标准可以收敛为一条：预填与解码的消息量是否相差足够大，使两阶段的最优 EP 度数分离。若分离，双度数配方加跨集群 RDMA 的固定开销可以被预填的大 token 数摊薄，解码的小 EP 度数把跳数压到可接受范围，解耦收益成立。若不分离，跨集群往返的额外网络跳数与序列化开销在小 batch decode 下超过 GEMM 计算时间，配方退化为纯开销。</p>\n<p>具体到部署决策：交互式低延迟服务、短输入短输出、解码批长期偏小的场景，不应把专家池剥离为独立集群，统一 EP 的两次 All-to-All 虽然同步，但跳数少、无跨集群序列化，端到端更短。长预填主导的离线批处理、文档级摘要、长上下文问答，预填批 token 数足以摊薄通信，解码批可按 SLO 聚到足够大，才是这套配方的目标负载。混合负载则要求调度器按长度分桶、按阶段分队列，并在专家集群侧保留重路由机制，否则专家集群故障会阻塞所有注意力 GPU，负载配方再优也无法阻止整个服务停摆。</p>\n<h3 id=\"alg-disagg-expert-parallel-sec-27\">二十七 · 硬件档位的三档切分与选型判据</h3>\n<p>部署配方的第一刀切在硬件档位上。分离式专家并行把集群拆成两类物理资源：注意力 GPU 与专家集群 GPU。两者对硬件的敏感点不同——注意力侧吃的是 KV cache 容量与 attention 算力，专家侧吃的是权重带宽与分组 GEMM 的吞吐。在 Blackwell 上，这两类负载的档位选择可以按互联能力而非单纯算力来划分。</p>\n<p>第一档是同节点内分离：注意力 GPU 与专家集群共享一台 GB200 NVL72 机柜，跨集群通信走 NVLink 5 域内链路，dispatch/combine 消息不经过网卡序列化。这一档的代价是资源耦合——专家集群无法跨机柜独立扩缩容，注意力与专家争抢同一批 GPU 的功耗预算。第二档是跨机柜 RDMA 分离：注意力集群与专家集群各自成柜，跨集群走 RDMA 网卡，此时每层两次跨集群往返引入完整的序列化与网络跳数开销。第三档是异构档位：注意力侧用高显存配比的 GPU 承载长上下文 KV，专家侧用高带宽配比的 GPU 承载专家权重，两侧按各自瓶颈独立选型。</p>\n<p>选型判据落在通信占比上。用前文的层时延公式衡量：</p>\n<div class=\"formula\">$$T_{\\text{layer}}=T_{\\text{attn}}+\\underbrace{\\frac{S_{\\text{token}}\\,N_{\\text{token}}}{\\text{BW}_{\\text{link}}}}_{T_{\\text{dispatch}}}+T_{\\text{gemm}}+\\underbrace{\\frac{S_{\\text{out}}\\,N_{\\text{token}}}{\\text{BW}_{\\text{link}}}}_{T_{\\text{combine}}}$$</div>\n<p>当 $T_{\\text{dispatch}}+T_{\\text{combine}}$ 在 $T_{\\text{layer}}$ 中的占比超过 $T_{\\text{gemm}}$ 时，跨机柜分离的收益被通信吃掉，应退回同节点档位或压缩 EP 度数。工程上把这个判据做成部署前的静态估算：给定 $N_{\\text{tok}}$、$k$、$d_{\\text{model}}$ 与链路带宽，先算出 dispatch 消息量 $M_{\\text{disp}} = N_{\\text{tok}} \\times k \\times (d_{\\text{model}} + w_{\\text{route}})$，再与专家集群的分组 GEMM 时间对比，决定档位。具体例子：一个 top-k 路由的 MoE 层，在 decode 阶段 $N_{\\text{tok}}$ 很小但每 token 都要走两次跨集群往返，此时 $T_{\\text{dispatch}}$ 由固定网络跳数主导而非带宽主导，同节点档位明显优于跨机柜档位。</p>\n<p>硬件档位还决定功耗分配。专家集群独立成柜后，其功耗预算只服务分组 GEMM 与权重读取，不再与注意力侧的 KV 读写争抢；这是分离部署在稳定性上的隐性收益，但代价是机柜级散热与供电的独立规划成本。</p>\n\n<h3 id=\"alg-disagg-expert-parallel-sec-28\">二十八 · 并行拓扑：EP 度数、分组粒度与拓扑映射</h3>\n<p>并行拓扑在分离式架构下有两个独立可调的自由度：注意力集群内部的张量并行度，与专家集群内部的 EP 度数。前文已给出预填用大 EP、解码用小 EP 的负载配方，这里补的是拓扑如何映射到物理链路。</p>\n<p>专家集群内部按专家并行分组 GEMM，EP 度数决定专家权重在多少张 GPU 上切分。大 EP 度数把单个专家的权重切得更碎，每张 GPU 读取的权重字节数下降，预填阶段的大 batch 能摊薄这次读取；但 EP 度数越大，dispatch 消息需要跨越的 GPU 越多，All-to-All 的跳数上升。小 EP 度数把多个专家放在同一张 GPU 上，decode 时 token 只需跨少量 GPU 往返，通信跳数降低，代价是单卡权重占用上升、显存预留变紧。</p>\n<p>拓扑映射的关键约束是专家 ID 到物理 GPU 的放置必须与链路拓扑对齐。若专家集群跨多个机柜，同一 token 的 top-k 专家若落在不同机柜，dispatch 消息要拆成多条跨柜路径，序列化开销翻倍。可行的做法是把高频共现的专家放在同一 NVLink 域内，把长尾专家放到跨柜位置，用路由统计驱动放置。这一放置策略与容量因子路由共享同一批路由统计，但目的不同：前者优化通信拓扑，后者控制令牌丢弃。</p>\n<p>注意力集群内部的张量并行度则受 KV cache 分片约束。张量并行度越高，每卡 KV 分片越小，但 attention 的集合通信次数上升。分离式架构允许注意力侧独立选择张量并行度而不牵连专家侧 EP 度数，这是相比统一 EP 的核心自由度。代价是两侧的并行度配置需要联合调参：注意力侧张量并行度变化会改变每卡发出的 token 数，进而改变专家集群的 dispatch 消息分布，配置不当会造成专家集群负载倾斜与显存预留浪费。</p>\n<p>一个可复现的拓扑起点：注意力集群按 KV 容量需求定张量并行度，专家集群按预填/解码两套 EP 度数分别配置，预填用大 EP 摊薄权重读取，解码用小 EP 降低跳数，两套配置共享同一批专家权重放置，仅切换分组 GEMM 的切分方式。</p>\n\n<h3 id=\"alg-disagg-expert-parallel-sec-29\">二十九 · 量化方案：两侧分别定精度档</h3>\n<p>量化方案在分离式架构下不能一刀切，因为注意力侧与专家侧的数值敏感点不同。注意力侧的核心是 KV cache 的精度与 attention 的数值稳定性；专家侧的核心是专家权重的微缩放量化与分组 GEMM 的累加精度。</p>\n<p>专家侧的量化选择直接决定权重读取带宽。NVFP4 的微缩放量化把专家权重压到 4 比特块，权重读取字节数下降，分组 GEMM 的吞吐上升；代价是激活也需要对应的微缩放格式，dispatch 消息中的 token 激活若以高精度传输，则量化收益只在权重侧兑现，激活传输仍是瓶颈。工程判断是：dispatch 消息的激活精度应与专家侧 GEMM 的输入格式对齐，避免在专家集群入口做一次反量化再量化。前文已讨论 NVFP4 权重激活微缩放量化的细节，此处只强调部署侧的取舍——专家集群的量化档位应与 dispatch 消息的序列化格式绑定，作为一个整体配置项。</p>\n<p>注意力侧的量化焦点在 KV cache。分页 KV 与专家权重共存显存的前文已给出显存预算方法，这里补的是精度档：KV cache 用 FP8 存储可把每 token 的 KV 字节数减半，直接提升可并发序列数；但 attention 的 softmax 累加若在低精度下做，长上下文会出现数值漂移。可行配置是 KV 存储用 FP8、attention 计算用更高精度累加，代价是每次 attention 需要一次格式转换，增加少量算力开销。</p>\n<p>两侧量化档位的联合约束是端到端误差预算。专家侧 NVFP4 引入的权重误差会经 combine 加权合并后进入下一层，与注意力侧 KV 量化的误差叠加。部署时把两侧的量化档位作为一对配置项联合评估，而不是各自独立选最优。具体例子：专家侧从 FP8 降到 NVFP4 带来的吞吐收益，若被注意力侧为补偿误差而提升的 KV 精度抵消，则整体不划算。</p>\n\n<h3 id=\"alg-disagg-expert-parallel-sec-30\">三十 · KV 策略：容量、分页与跨集群可见性</h3>\n<p>分离式架构下 KV cache 全部落在注意力 GPU 上，专家集群不持有 KV。这一分工使 KV 策略成为注意力集群的独立优化面，但也带来一个部署约束：KV 容量决定注意力集群的规模下限，而专家集群的规模由专家权重与 EP 度数决定，两者不再同步扩缩容。</p>\n<p>KV 策略的第一个参数是每卡 KV 预算。给定模型层数、头数与隐藏维，每 token 的 KV 字节数在选定精度后固定，每卡可承载的并发 token 数由显存扣除权重与激活后的余量除以每 token KV 字节数得出。这个数字直接决定注意力集群需要多少张 GPU 才能满足目标并发。分离式架构的收益在此显现：注意力集群可以只按 KV 容量扩容，不必为了专家权重而同步增加 GPU。</p>\n<p>第二个参数是分页粒度。分页 KV 把 cache 切成固定大小的块，块大小影响显存碎片率与页表开销。块太小则页表膨胀、寻址开销上升；块太大则尾部浪费、短序列的显存利用率下降。部署时按请求长度分布选块大小，长预填短解码的服务形态适合中等块大小，兼顾长序列的连续分配与短序列的尾部浪费。</p>\n<p>第三个参数是 KV 的跨集群可见性。专家集群计算时不读 KV，但 combine 回传的 token 需要与发起 GPU 上的 KV 位置对齐。若注意力集群内部做了张量并行或序列并行，KV 分片与 token 归属的映射必须在 dispatch 消息中携带，否则 combine 回传时无法定位。这是部署配方中容易被忽略的一项：dispatch 消息的元数据除路由权重外，还需包含 token 的原索引与 KV 分片标识。</p>\n<p>代价层面，KV 策略的调整会反向影响专家集群的负载。KV 容量提升带来更大并发，decode 阶段的 batch 变大，专家集群的 dispatch 消息量随之上升，小 EP 度数下的通信跳数优势被更大的消息量稀释。因此 KV 策略与 EP 度数需要联合调参，而非各自独立最优。</p>\n\n<h3 id=\"alg-disagg-expert-parallel-sec-31\">三十一 · 调度参数：批大小、超时与容错重路由</h3>\n<p>调度参数是部署配方里唯一需要在运行期持续调整的部分。分离式架构把预填与解码的调度解耦，两侧可以各自设定批大小与排队策略，但跨集群的 dispatch/combine 引入了一个新的调度维度：跨集群往返的超时与重试。</p>\n<p>批大小按 SLO 调节，材料未给出具体数值，但调节方向明确：预填阶段用大批摊薄专家权重读取，解码阶段用小批降低单次往返的固定开销占比。分离式架构允许预填与解码使用不同的批大小上限，这是统一 EP 做不到的——统一 EP 下预填的大批会把解码的小批挤在同一套 All-to-All 同步里，解码被预填的通信拖慢。</p>\n<p>超时参数针对跨集群往返。dispatch 消息发出后，专家集群的分组 GEMM 时间加上 combine 回传时间构成一次往返的期望时延。超时阈值应设为该期望时延的倍数，超时后触发重路由：把该 token 的专家计算重新派发到备用专家副本，或退回本地计算路径。重路由机制是容错的核心，因为专家集群故障会阻塞所有注意力 GPU，缺乏重路由时整个服务停摆。</p>\n<p>容错重路由的代价是显存预留。备用专家副本需要额外的权重显存，这部分显存不参与常规分组 GEMM，只在故障时启用。预留比例与故障率、恢复时间挂钩，部署时作为专家集群的固定开销计入容量规划。另一个代价是重路由引入的额外往返，故障期间 decode 的时延会上升，SLO 需要为故障窗口留出余量。</p>\n<p>调度参数还包括专家集群内部的负载均衡阈值。预填与解码 EP 度数配置不当会造成专家集群负载倾斜：大 EP 下某些专家所在 GPU 收到过多 token，分组 GEMM 排队，而其他 GPU 空闲。部署时按路由统计设定每个专家的 token 上限，超过上限的 token 走重路由或丢弃，这一机制与容量因子路由共享实现，但在分离式架构下阈值需要按 EP 度数分别设定——预填的大 EP 与小 EP 解码的阈值不同。</p>\n<p>一个可复现的配置思路：先按 KV 容量定注意力集群规模与张量并行度，再按专家权重与预填/解码两套 EP 度数定专家集群规模，两侧量化档位联合评估，KV 分页粒度按请求长度分布选中等块，调度侧为预填与解码各设批大小上限，跨集群往返设超时与重路由，专家集群按故障率预留备用副本显存。这套配置的验证点是层时延公式中通信项与 GEMM 项的实际占比，若通信项在 decode 阶段超过 GEMM 项，则退回更小 EP 度数或同节点档位。</p>\n<h3 id=\"alg-disagg-expert-parallel-sec-32\">三十二 · 逐层代价账：把 T_layer 拆成五项可归因的预算</h3>\n<p>分离式专家并行（disaggregated EP）的性能账不能只算 GEMM，必须把每层时间拆成注意力、dispatch、专家 GEMM、combine 四段，任何一段越界都会把整层拖进 SLO 违约区。可用公式给出结构：</p>\n<div class=\"formula\">$$T_{\\text{layer}}=T_{\\text{attn}}+\\underbrace{\\frac{S_{\\text{token}}\\,N_{\\text{token}}}{\\text{BW}_{\\text{link}}}}_{T_{\\text{dispatch}}}+T_{\\text{gemm}}+\\underbrace{\\frac{S_{\\text{out}}\\,N_{\\text{token}}}{\\text{BW}_{\\text{link}}}}_{T_{\\text{combine}}},\\quad \\text{EP}_{\\text{opt}}=\\arg\\min_{\\text{EP}}\\left(T_{\\text{gemm}}(\\text{EP})+T_{\\text{comm}}(\\text{EP})\\right)$$</div>\n<p>这里的关键不是公式本身，而是两项通信时间与 EP 度数的耦合方向相反：EP 越大，专家权重被切得越碎，单卡权重读取量下降、T_gemm 降低；但跨集群跳数、消息序列化与排队时延上升，T_comm 抬高。最优 EP 是这条 U 形曲线的谷底，而谷底位置随 batch 形态漂移——预填 batch 大、T_gemm 占主导，谷底偏大 EP；decode batch 小、T_comm 占主导，谷底偏小 EP。这正是分离式部署允许预填与解码各选 EP 度数的物理依据，而不是一句“灵活”能概括的。</p>\n<p>工程上要把这条账做成可观测的：按层打点 T_attn、T_dispatch、T_gemm、T_combine，用滑动窗口统计各段占比。当 dispatch+combine 占比超过某阈值（由 SLO 的 TPOT 预算反推），说明当前 EP 度数对该 batch 形态过大，应下调；反之若 T_gemm 占比持续偏高且专家集群利用率不满，说明 EP 偏小、权重读取没摊薄。代价落在延迟上：一次 EP 度数切换要重建专家分组与路由表，切换窗口内的请求会经历拓扑重配的抖动，因此切换应绑定在批形态稳定期而非逐批抖动。</p>\n<p>具体例子：长预填加短解码的自回归服务，预填阶段单批 token 数大，dispatch 消息量与 combine 消息量同阶放大，但 T_gemm 因权重摊薄而显著下降，大 EP 划算；解码阶段每步只带少量 token，dispatch 消息量小但固定跳数与序列化开销不变，跨集群往返可能超过分组 GEMM 本身，此时小 EP 减少跳数才是正解。材料未给出具体批大小与 SLO 数值，因此阈值必须由部署方用自己的打点数据标定，不能照搬。</p>\n\n<h3 id=\"alg-disagg-expert-parallel-sec-33\">三十三 · 显存账：专家权重、分页 KV 与预留浪费的三方挤占</h3>\n<p>分离式部署把显存压力切成两块：注意力 GPU 侧主要是 KV cache 与激活，专家集群侧主要是专家权重与分组 GEMM 的临时缓冲。看似解耦，实则存在隐式耦合——专家集群按 EP 分组后，每组 GPU 必须为分到的专家预留权重空间，而路由倾斜会让某些专家所在卡的热度远高于其他卡，显存预留按最坏情况做，于是出现“预留浪费”：冷专家占着显存不干活，热专家卡却因缓冲不足而排队。</p>\n<p>dispatch 消息量给出显存侧的第一个约束：</p>\n<div class=\"formula\">$$M_{\\text{disp}} = N_{\\text{tok}} \\times k \\times (d_{\\text{model}} + w_{\\text{route}})$$</div>\n<p>其中 N_tok 为 token 数、k 为 top-k、d_model 为隐藏维、w_route 为路由权重字节数，combine 消息量同阶。这条式子同时是网络带宽账和显存账：dispatch 缓冲要按 M_disp 的峰值分配，若预填 batch 很大而专家集群入口缓冲按解码峰值配置，就会出现入口阻塞，反过来压制注意力 GPU 的发射节奏。工程判断是：入口缓冲按预填峰值配、出口 combine 缓冲按解码峰值配，两者不共用同一块池，否则预填与解码的波峰叠加会互相踩踏。</p>\n<p>代价落在显存容量与带宽上：专家权重在 EP 分组后单卡占用下降，但分组 GEMM 的中间结果与 token 重排缓冲随 batch 线性增长；KV cache 在注意力侧按分页管理，其增长与专家集群无关，却决定了注意力 GPU 能撑多大的并发。二者若共用同一批 GPU（非完全分离的过渡形态），就会出现分页 KV 与专家权重争抢同一显存池的局面，此时必须给专家权重设硬上限，把剩余空间全部分页 KV，避免权重增长悄悄吃掉 KV 容量导致并发骤降。</p>\n<p>具体例子：某层路由把大量 token 集中到少数专家，这些专家所在 GPU 的分组 GEMM 缓冲被打满，而同组其他 GPU 空闲；若缓冲按平均负载配置，热卡会触发同步等待，整层 T_gemm 被最慢卡决定。解法不是加大总缓冲，而是按专家热度做非均匀预留并把冷专家的显存回收给分页 KV 或下一组专家，这属于部署配方层面的容量因子调节，此处只点出代价归属。</p>\n\n<h3 id=\"alg-disagg-expert-parallel-sec-34\">三十四 · 带宽与通信：跳数、序列化与 RDMA 消息率的乘性叠加</h3>\n<p>跨集群通信的代价不是单一带宽数字能描述的，它由三部分乘性叠加：跳数决定的传播时延、消息大小决定的序列化时延、消息率决定的 NIC 与交换机排队。分离式 EP 把原本集群内的 All-to-All 变成“注意力 GPU → 专家集群入口 → 专家所在 GPU → 回程”的路径，跳数增加是结构性的，无法靠调优消除，只能靠减少往返次数或合并消息摊薄。</p>\n<p>带宽账的直接形式是 T_dispatch 与 T_combine 中的 S_token·N_token/BW_link：消息越大，带宽项越重；但消息小时，固定开销（每消息的头部、序列化、DMA 描述符）占比上升，此时有效带宽远低于链路峰值。工程上的判断是设一个消息大小下限，低于该下限就把多个 token 的 dispatch 合并成一条消息发送，用批量换取固定开销摊薄；代价是合并引入的等待窗口，窗口长度必须小于解码步间隔，否则合并反而增加尾延迟。</p>\n<p>代价落在吞吐与尾延迟两侧：吞吐由链路有效带宽与消息率共同决定，尾延迟由最慢的那条消息决定。分离式部署中，combine 消息要回传到发起 GPU 并按路由权重加权合并，回程路径上任何一跳的排队都会直接进入下一层的关键路径，因此 combine 的优先级应高于 dispatch——dispatch 可以容忍轻微排队（下一层还没开始），combine 不能。这要求 RDMA 侧做分级队列，而不是把所有 MoE 流量塞进同一优先级。</p>\n<p>具体例子：解码阶段每步 token 数少，dispatch 消息量小，但每层仍要走两次跨集群往返；若每消息固定开销在微秒量级，层数一多，固定开销累加就可能超过分组 GEMM 的计算时间。这正是材料指出的失败模式：小 batch decode 下跨集群往返时延可能超过分组 GEMM，抵消解耦收益。对策是解码用小 EP 度数降低跳数，并在专家集群内部用更紧的拓扑把回程跳数压到最少，而不是靠加大带宽硬扛。</p>\n\n<h3 id=\"alg-disagg-expert-parallel-sec-35\">三十五 · 功耗与热：专家集群的利用率空洞如何变成电费</h3>\n<p>分离式 EP 的功耗账有一个反直觉之处：解耦提升了灵活性，却可能降低整体能效。原因是专家集群的利用率随路由倾斜而波动，冷专家所在 GPU 在低利用率下仍要保持时钟与供电，形成“利用率空洞”；而注意力 GPU 为了等 combine 回传，发射节奏被拖慢，SM 占用率下降，单位 token 的能耗上升。功耗代价不体现在峰值功率，而体现在每 token 焦耳数随 batch 形态恶化。</p>\n<p>机制上，专家集群的分组 GEMM 是突发型负载：dispatch 到达时集中计算，空闲时几乎不干活。这种占空比让 GPU 频繁进出高功耗状态，DVFS 的响应滞后于突发节奏，导致要么在空闲期浪费静态功耗，要么在突发期因升频不及时而拉长 T_gemm。工程判断是把专家集群的批处理窗口拉长，用更大的分组 GEMM 摊薄突发次数，代价是 dispatch 排队时延增加——这与尾延迟要求直接冲突，需要在 SLO 预算内做取舍。</p>\n<p>代价归属要分清：注意力 GPU 侧的功耗由 KV cache 读写与注意力计算主导，专家集群侧的功耗由权重读取与分组 GEMM 主导，两者解耦后可以分别设定功率上限。若把两侧混在同一功率域，专家集群的突发会把注意力侧的可用功率挤掉，造成 decode 步间隔抖动。分离部署的物理意义之一就是让两侧各自有独立的功率与散热预算，而不是共享一个机柜功率帽。</p>\n<p>具体例子：预填阶段专家集群满负荷、注意力 GPU 相对空闲；解码阶段反过来。若两侧共用功率帽，预填波峰会触发整体降频，解码阶段的注意力计算被连带拖慢。分离部署后，预填波峰只影响专家集群功率域，注意力侧保持稳定时钟，decode 的 TPOT 抖动被压住。材料未给出具体功耗数值，因此这里只做定性归因：功耗代价的核心是利用率空洞与功率域耦合，而非峰值功耗本身。</p>\n\n<h3 id=\"alg-disagg-expert-parallel-sec-36\">三十六 · 尾延迟：故障域放大与重路由的代价传导</h3>\n<p>分离式 EP 把故障域从“单卡影响单层”放大为“专家集群影响所有注意力 GPU”。材料明确指出：专家集群故障会阻塞所有注意力 GPU，缺乏重路由时整个服务停摆。这不是可用性套话，而是尾延迟的结构性来源——一次专家集群的慢节点或链路抖动，会让所有在途请求的 combine 回传延迟，尾延迟分位数直接被最慢的那条路径决定。</p>\n<p>机制上，重路由是唯一的缓解手段：检测到某专家所在 GPU 不可达或超时，把该专家的 token 改派到副本专家或降级到次优专家，同时把原路由权重按比例重分配。重路由的代价是双重的：一是检测窗口内的请求已经排队，尾延迟已经发生；二是重路由本身要重建路由表并可能触发专家权重的重新加载，这段时间专家集群的有效容量下降。工程判断是把重路由做成预热的：副本专家常驻显存但不参与常规路由，只在故障时接管，用显存换尾延迟稳定性。</p>\n<p>尾延迟的另一个来源是预填与解码 EP 度数配置不当造成的负载倾斜。材料指出这会带来专家集群负载倾斜与显存预留浪费。倾斜的后果是最热专家所在 GPU 成为整层的瓶颈卡，T_gemm 由它决定，而其他卡空闲；此时尾延迟不是由平均负载决定，而是由最热卡决定。解法是按热度做非均匀分组，把热专家拆到多张卡上做张量并行或副本，代价是权重副本占用显存、通信量上升。</p>\n<p>具体例子：解码阶段小 EP 度数下，某专家被大量 token 选中，其所在 GPU 的分组 GEMM 排队，combine 回传被推迟，注意力 GPU 等回传而无法进入下一层，TPOT 尾部拉长。此时加大 EP 度数能摊薄该专家的负载，但跳数增加又会抬高固定开销——这正是 EP_opt 需要按 batch 形态动态求解的原因，而不是固定一个度数跑到底。</p>\n\n<h3 id=\"alg-disagg-expert-parallel-sec-37\">三十七 · 规模上去以后哪里先崩：按代价项的排序判断</h3>\n<p>规模扩展时各代价项的增长斜率不同，先崩的那一项决定了系统的实际上限。按可用事实排序：跨集群网络跳数与序列化开销是结构性的，随规模线性甚至超线性增长（跳数随集群分层增加），且无法靠单点优化消除；专家集群故障域随规模放大，重路由的检测与恢复窗口随节点数增加而变长；显存预留浪费随专家数与路由倾斜程度上升；功耗与散热随机柜密度逼近上限。四者中，网络跳数与序列化开销最先成为硬约束，因为它是唯一无法通过增加资源直接抵消的项——加卡只会增加跳数与消息率。</p>\n<p>判断依据是 T_comm 与 T_gemm 的比值随规模的变化方向。规模上升时，T_gemm 因权重摊薄而下降或持平，T_comm 因跳数与消息率上升而增长，二者比值单调上升，直到 T_comm 主导整层时间。此时继续扩 EP 度数不再降低 T_layer，反而抬高它，EP_opt 向小度数回移。这就是材料所说“规模上限受跨集群网络跳数与序列化开销约束”的定量含义：上限不是某个卡数，而是 T_comm 超过 T_gemm 的那个交点。</p>\n<p>工程上的应对不是硬扛，而是改变拓扑：把专家集群从“跨机柜分层”压成“机柜内扁平”，用更少的跳数换取更大的 EP 度数空间；或者把热专家做成机柜内副本，让大部分 dispatch 不出机柜。代价是机柜内带宽与显存被副本占用，且副本一致性维护增加复杂度。另一个方向是把 decode 的 EP 度数锁在小值、把预填的 EP 度数放大，让两类流量走不同拓扑，避免 decode 被预填的大 EP 拓扑拖进高跳数路径。</p>\n<p>具体例子：当专家集群跨多个机柜分层互联时，一次 dispatch 可能经过两级交换，combine 回程再走两级，单层往返跳数翻倍；此时即使分组 GEMM 很快，T_layer 也被通信段吃掉。把专家集群收敛到单机柜内、用 NVLink 域承载大部分 All-to-All，跳数下降，EP_opt 的谷底右移，大 EP 度数重新变得划算。这个判断落在拓扑选择上，而不是参数调优上——规模上去以后先崩的是跳数账，先修的也必须是拓扑。</p>\n<h3 id=\"alg-disagg-expert-parallel-sec-38\">三十八 · 精度漂移：dispatch/combine 路径上的静默误差</h3>\n<p>分离式专家并行把一次前向切成“注意力 GPU 路由 → RDMA dispatch → 专家集群分组 GEMM → combine 回传”四段，精度问题几乎全部集中在跨集群边界上。最典型的失败模式是<strong>路由权重与激活值的字节宽度不一致</strong>：注意力侧按 FP32 算出的 top-k 权重，打包进 dispatch 消息时若被截成低精度，combine 阶段加权合并就会产生系统性偏差——不是随机噪声，而是按专家 ID 聚集的偏置，表现为某些专家的输出整体偏大或偏小。第二种是<strong>分组 GEMM 的累加精度</strong>：专家集群内按专家 ID 分组后，每组 token 数不等，若分组 GEMM 用低精度累加器且未做分块补偿，长尾专家（token 少但权重读取完整）的相对误差被放大。第三种最隐蔽：<strong>dispatch 消息的序列化顺序与 combine 的索引还原不匹配</strong>，token 索引打包时若依赖隐式排序而非显式 token id，重路由或重试会导致结果错位，数值上看只是“轻微退化”，实际是样本级串扰。</p>\n<p>诊断手段要落在消息边界上。对每一层记录三个量：dispatch 消息的权重和 $\\sum_i w_i$（应恒等于 top-k 归一化后的常数）、combine 回传的 token 索引集合与发起侧集合的差集、以及分组 GEMM 每组 token 数的分布。前两个量出现漂移即定位到打包/还原逻辑，第三个量出现极端偏斜则指向路由不均而非数值本身。精度回滚的工程判断很直接：<strong>把 dispatch 权重字节宽度与专家集群 GEMM 累加精度解耦配置</strong>，权重始终走与注意力侧一致的宽度，GEMM 累加精度单独可调，这样精度问题可以被隔离到单一开关上，而不必整体回退部署拓扑。</p>\n<div class=\"formula\">$$M_{\\text{disp}} = N_{\\text{tok}} \\times k \\times (d_{\\text{model}} + w_{\\text{route}})$$</div>\n<p>这个式子同时是精度审计的单位：$w_{\\text{route}}$ 的字节数决定了权重在传输中能被保留多少位，$d_{\\text{model}}$ 的宽度决定了激活的量化误差。代价上，把 $w_{\\text{route}}$ 从低精度抬回高精度只增加 dispatch 消息的头部字节，对 $\\text{BW}_{\\text{link}}$ 的占用增量远小于激活本身，属于低代价高收益的回滚动作；反之抬高 $d_{\\text{model}}$ 的传输精度会直接按比例吃掉跨集群带宽，在小 batch decode 下会与 GEMM 时间正面竞争。</p>\n\n<h3 id=\"alg-disagg-expert-parallel-sec-39\">三十九 · OOM 的三条来源与显存预留的错配</h3>\n<p>分离式部署把显存压力从“一张卡上注意力 + 专家权重 + KV cache 混住”变成两个独立池，但 OOM 并没有消失，只是换了位置。第一条来源是<strong>专家集群侧的权重预留</strong>：专家集群按 EP 度数切分专家权重，EP 度数选大则单卡权重少、但每卡要预留更多 dispatch 缓冲；EP 度数选小则权重集中、缓冲少但单卡权重读取压力大。预填用大 EP、解码用小 EP 的配方意味着同一批物理卡要在两种预留之间切换，若缓冲按峰值静态分配，解码阶段就会留下大量闲置预留——这是“预留浪费”型 OOM 的反面：不是不够，而是分配策略把可用显存锁死在错误的形状上。第二条来源是<strong>注意力 GPU 侧的 combine 缓冲</strong>：combine 消息按原 token 索引回传，缓冲大小与在飞 token 数成正比，连续批处理下批大小抖动会让缓冲需求瞬时超过静态上限。第三条是<strong>跨集群重路由的副本</strong>：专家集群故障触发重路由时，同一批 token 可能被同时发往主路径与备份路径，缓冲瞬间翻倍。</p>\n<p>诊断 OOM 要看“谁在什么时候占了什么形状”，而不是只看总量。工程上有效的做法是给 dispatch 缓冲与 combine 缓冲分别打上按 EP 度数区分的标签，观察预填/解码切换时刻的占用曲线；若曲线在切换点出现锯齿，说明预留未随 EP 度数重算。回滚路径是把缓冲从静态预留改为<strong>按当前 EP 度数与在飞 token 数动态计算上限</strong>，并把重路由副本计入上限公式而非额外叠加。代价是动态分配引入分配器抖动，在 decode 的微秒级步进里可能表现为批抖动，因此动态上限需要配合预分配池使用，而不是每步向运行时申请。</p>\n\n<h3 id=\"alg-disagg-expert-parallel-sec-40\">四十 · 批抖动与路由不均：两个互相放大的失败模式</h3>\n<p>批抖动在分离式架构里有独特成因：注意力 GPU 与专家集群是两个独立的调度域，注意力侧按 SLO 调批大小，专家集群按到达的 dispatch 消息排队，两侧的批边界不对齐。当注意力侧放大批以提升吞吐时，专家集群收到的是突发的大批 dispatch，分组 GEMM 的组数骤增、每组 token 数骤降，GEMM 效率塌陷；当注意力侧缩批以压尾延迟时，专家集群又因消息太小而无法摊薄权重读取。这种“批大小在两个域之间被反复重解释”的现象，表现为端到端吞吐随批大小非单调，且延迟分布出现双峰。</p>\n<p>路由不均则是它的放大器。top-k 路由天然不均衡，少数热门专家收到的 token 数远超均值，专家集群内按专家 ID 分组后，热门专家所在 GPU 成为瓶颈，其余 GPU 空转等待 combine 屏障。两者叠加时，批抖动让不均的分布每步都在变，无法用静态的专家到 GPU 映射吸收。诊断指标应包含<strong>每专家 token 数的基尼系数或最大/均值比</strong>，以及分组 GEMM 各组的实际占用率；前者定位路由层，后者定位计算层。工程判断是：路由不均不能靠加大 EP 度数解决（度数越大，跨集群跳数越多，小 batch decode 下通信时延越可能超过 GEMM），而应靠<strong>专家副本与重路由</strong>把热门专家摊到多张卡，代价是权重显存按副本数翻倍，需要在专家集群独立扩缩容的能力内消化。</p>\n<table class=\"mini\"><thead><tr><th>失败模式</th><th>可观测信号</th><th>主要代价</th><th>回滚动作</th></tr></thead><tbody><tr><td>精度漂移</td><td>dispatch 权重和偏离常数、索引差集非空</td><td>跨集群带宽（抬精度时）</td><td>权重宽度与 GEMM 累加精度解耦</td></tr><tr><td>OOM</td><td>EP 切换点缓冲占用锯齿</td><td>显存预留浪费</td><td>缓冲上限按 EP 度数与在飞 token 动态算</td></tr><tr><td>批抖动</td><td>吞吐随批大小非单调、延迟双峰</td><td>GEMM 效率塌陷</td><td>两域批边界对齐或专家侧按消息聚合</td></tr><tr><td>路由不均</td><td>每专家 token 数最大/均值比高</td><td>权重显存按副本翻倍</td><td>热门专家副本 + 重路由</td></tr><tr><td>尾延迟尖刺</td><td>combine 屏障等待时间突增</td><td>decode 步进被拉长</td><td>故障专家摘除 + 备份路径预热</td></tr></tbody></table>\n\n<h3 id=\"alg-disagg-expert-parallel-sec-41\">四十一 · 尾延迟尖刺：故障阻塞与重路由的代价结构</h3>\n<p>分离式专家并行最严重的稳定性缺陷是<strong>专家集群故障会阻塞所有注意力 GPU</strong>：注意力侧发出 dispatch 后进入等待，combine 不回则整条 decode 流水停摆，缺乏重路由时整个服务停摆。尾延迟尖刺因此不是“慢一点”，而是“卡住”——单张专家 GPU 掉线或 RDMA 路径抖动，会让所有在飞 token 的 combine 屏障超时。诊断上要把 dispatch 发出到 combine 收到的往返时间按专家 ID 与目标 GPU 分别统计，尖刺若集中在单一目标 GPU，是硬件或进程故障；若弥散在所有目标上，是网络路径或序列化开销问题。</p>\n<p>重路由机制的设计决定了尖刺的幅度。备份路径若在故障时才建立连接，重连与序列化开销会叠加在已经超时的往返上；若备份路径常驻预热，则代价是专家集群需要按副本数预留权重显存与缓冲。工程判断是<strong>按专家热度分级预热</strong>：热门专家的备份路径常驻，长尾专家走按需重路由，把显存代价压在少数专家上。另一个必须监控的量是重路由期间的重复 dispatch 率——同一 token 被发往主备两路时，专家集群的 GEMM 负载会瞬时上升，若此时又叠加批抖动，分组 GEMM 的组数会突破缓冲上限，把尾延迟尖刺转化为 OOM。</p>\n\n<h3 id=\"alg-disagg-expert-parallel-sec-42\">四十二 · 监控面与回滚顺序</h3>\n<p>监控面要按“域”切分而不是按“卡”切分：注意力域看路由分布与 combine 等待时间，专家域看分组 GEMM 组数与每组占用率，跨域看 dispatch/combine 消息量 $M_{\\text{disp}}$ 与往返时延。三个域各自有独立的扩缩容与回滚开关，这正是解耦部署的价值——精度问题只动专家域 GEMM 配置，OOM 只动缓冲上限，路由不均只动专家副本映射，不必整体回退拓扑。回滚顺序应按影响面从小到大：先摘除故障专家并切备份路径（影响单专家），再调缓冲上限（影响单域显存），再改 EP 度数（影响预填/解码配方），最后才回退到统一 EP 部署（放弃解耦收益）。</p>\n<p>需要强调的是，EP 度数的调整本身就是一个失败模式来源：预填与解码 EP 度数配置不当会造成专家集群负载倾斜与显存预留浪费。因此 EP 度数不应作为在线回滚的第一手段，而应作为离线配方的一部分，在线只做专家副本与缓冲的微调。容量规划上，专家集群的独立扩缩容能力必须覆盖“热门专家副本 + 备份路径预热”的显存需求，否则重路由机制会在最需要它的时候因显存不足而失效。</p>\n<p>最后落在具体机制上：把 dispatch 消息的权重和、combine 索引差集、每专家 token 数最大/均值比、分组 GEMM 组占用率、以及按目标 GPU 分桶的往返时延，作为五个常驻指标接入告警；任一指标越界时，按“摘专家 → 调缓冲 → 改副本 → 回退拓扑”的顺序执行回滚，且每一步都有独立的显存与带宽代价核算。这套监控与回滚结构不是运维附属品，而是分离式专家并行能否在小 batch decode 场景下维持收益的前置条件——当跨集群往返时延逼近分组 GEMM 时间时，任何一次未及时摘除的故障专家都会把解耦收益直接吃掉。</p>\n\n<h3 id=\"alg-disagg-expert-parallel-sec-43\">四十三 · 解耦架构的失效边界与可观测性设计</h3>\n<p>分离式专家并行把故障域从“单卡局部”放大为“跨集群全局”：专家集群一旦出现节点失联或分组 GEMM 阻塞，所有注意力 GPU 的 dispatch 消息都会在 RDMA 队列上堆积，而注意力侧并无本地专家权重可回退，缺乏重路由时整个服务直接停摆。诊断上必须把 dispatch 队列深度、combine 回传时延、专家侧分组 GEMM 排队长度三者做成同一时间轴上的关联指标——单看注意力 GPU 的 SM 利用率会误判为“算力空闲”，实际是 token 在网络上等待。回滚路径应预置“专家集群降级为统一 EP”的旁路开关，代价是重新引入每层两次 All-to-All 同步与 decode 通信时延占比上升，因此该开关只能作为短时止血而非稳态方案。</p>\n<p>小 batch decode 是本方案收益递减的硬边界。跨集群往返引入额外网络跳数与序列化开销，当 batch 小到分组 GEMM 无法摊薄权重读取时，通信时延超过计算时间：</p>\n<div class=\"formula\">$$T_{\\text{layer}}=T_{\\text{attn}}+\\underbrace{\\frac{S_{\\text{token}}\\,N_{\\text{token}}}{\\text{BW}_{\\text{link}}}}_{T_{\\text{dispatch}}}+T_{\\text{gemm}}+\\underbrace{\\frac{S_{\\text{out}}\\,N_{\\text{token}}}{\\text{BW}_{\\text{link}}}}_{T_{\\text{combine}}}$$</div>\n<p>此时应把 EP 度数按 <span>EP<sub>opt</sub>=argmin(T<sub>gemm</sub>(EP)+T<sub>comm</sub>(EP))</span> 收缩，或临时把该批 token 路由回注意力侧的统一 EP 通道。批抖动则表现为预填与解码 EP 度数切换时的负载倾斜：预填用大 EP 摊薄权重读取、解码用小 EP 降低跳数，若两阶段共享同一专家池而未做显存预留隔离，预填突发会把解码的专家副本挤出，造成尾延迟尖刺。监控需按 EP 度数分桶统计专家命中率与单专家 token 数方差，路由不均一旦超过阈值即触发重均衡。</p>\n<table class=\"mini\"><thead><tr><th>失败模式</th><th>可观测信号</th><th>处置</th></tr></thead><tbody><tr><td>专家集群故障</td><td>dispatch 队列深度持续上涨、combine 回传缺失</td><td>切统一 EP 旁路，重路由</td></tr><tr><td>小 batch 通信反超</td><td>T<sub>comm</sub>/T<sub>gemm</sub> 比值抬升</td><td>收缩 EP 度数或回退本地通道</td></tr><tr><td>批抖动/路由不均</td><td>单专家 token 方差、显存预留缺口</td><td>预填解码显存隔离，重均衡</td></tr></tbody></table>\n<h3 id=\"alg-disagg-expert-parallel-sec-44\">四十四 · 决策的第一性原理：把 EP 选择还原成两个可测量</h3>\n<p>选型不是选“先进”，而是选“当前瓶颈落在哪一项”。分离式专家并行把单层时间拆成四项：注意力、dispatch、专家 GEMM、combine。相邻算法（统一 EP、容量因子路由、专家选择路由、无丢弃块稀疏分组 GEMM、量化融合大核）本质上都在改写这四项中的一项或两项。因此决策表的第一列不应是算法名，而应是“当前 T_comm 与 T_gemm 谁占主导、以及预填与解码的比值是否分裂”。</p>\n<div class=\"formula\">$$T_{\\text{layer}}=T_{\\text{attn}}+\\underbrace{\\frac{S_{\\text{token}}\\,N_{\\text{token}}}{\\text{BW}_{\\text{link}}}}_{T_{\\text{dispatch}}}+T_{\\text{gemm}}+\\underbrace{\\frac{S_{\\text{out}}\\,N_{\\text{token}}}{\\text{BW}_{\\text{link}}}}_{T_{\\text{combine}}},\\quad \\text{EP}_{\\text{opt}}=\\arg\\min_{\\text{EP}}\\left(T_{\\text{gemm}}(\\text{EP})+T_{\\text{comm}}(\\text{EP})\\right)$$</div>\n<p>工程上把它变成两个可测量：一是 dispatch 消息量 $M_{\\text{disp}} = N_{\\text{tok}} \\times k \\times (d_{\\text{model}} + w_{\\text{route}})$，它随批大小线性增长，是解码小 batch 场景下的固定成本；二是专家权重读取量，它随 EP 度数增大而被摊薄。前者决定“通信是否值得解耦”，后者决定“解耦后 EP 度数往哪边走”。两个量都拿不到实测时，用链路带宽与单卡权重容量做保守估计即可，不要用“大概”替代测量。</p>\n<p>具体例子：长预填加短解码的自回归服务，预填 batch 大，$M_{\\text{disp}}$ 大但被 GEMM 摊薄，此时大 EP 度数把权重读取压到每卡可容纳；解码 batch 小，$M_{\\text{disp}}$ 小但 GEMM 也小，跨集群往返跳数与序列化开销成为主项，此时应退回小 EP 度数甚至统一 EP。代价判断：一次跨集群往返在小 batch decode 下可能超过分组 GEMM 时间，直接表现为 TPOT 抬升与 GPU 空转，功耗不降反升。</p>\n\n<h3 id=\"alg-disagg-expert-parallel-sec-45\">四十五 · 决策表：六种同族形态的适用条件</h3>\n<p>下表把本族与相邻算法放在同一张表里，列是触发条件，行是形态。判据全部落在可观测指标上：预填/解码的通信需求是否分裂、专家层是否已成为独立瓶颈、是否允许丢弃 token、权重能否放进单卡。</p>\n<table class=\"mini\"><thead><tr><th>形态</th><th>触发条件</th><th>主要收益项</th><th>主要代价项</th><th>不适用</th></tr></thead><tbody>\n<tr><td>统一 EP（基线）</td><td>预填与解码通信模式接近；集群规模小</td><td>实现简单、无跨集群跳数</td><td>解码被两次 All-to-All 拖慢</td><td>预填/解码需求分裂</td></tr>\n<tr><td>分离式专家并行</td><td>专家层成独立瓶颈；预填/解码 EP 需求分裂；有 RDMA 与独立扩缩容需求</td><td>decode 跳数降低；两层分别扩容</td><td>跨集群往返、序列化、故障域扩大</td><td>小 batch decode 为主、无容错重路由</td></tr>\n<tr><td>容量因子路由与令牌丢弃</td><td>专家负载倾斜严重、可容忍少量 token 丢弃</td><td>分组 GEMM 形状规整、显存预留可控</td><td>质量损失、丢弃不可逆</td><td>质量敏感任务</td></tr>\n<tr><td>专家选择路由</td><td>路由抖动导致负载不均、需稳定分组</td><td>负载更均衡、减少倾斜</td><td>路由计算与元数据开销</td><td>路由本身已均衡</td></tr>\n<tr><td>无丢弃块稀疏分组 GEMM</td><td>不允许丢弃、专家形状高度不规则</td><td>保住全部 token、GEMM 利用率提升</td><td>块稀疏元数据与 kernel 复杂度</td><td>形状已规整、丢弃可接受</td></tr>\n<tr><td>量化融合大核（NVFP4/FP8）</td><td>权重带宽是主瓶颈、精度预算允许</td><td>权重读取字节数下降、GEMM 吞吐上升</td><td>量化误差、校准成本</td><td>精度敏感层</td></tr>\n</tbody></table>\n<p>读表方法：先看第二列是否命中，再看第四列是否可承受。分离式专家并行与量化融合大核是正交的——前者改通信拓扑，后者改字节数，可以叠加；但与容量因子路由叠加时要小心，丢弃会改变 $M_{\\text{disp}}$ 的有效 token 数，使按 SLO 调的批大小失真。代价上，量化把权重读取压下来后，$T_{\\text{comm}}$ 占比反而上升，此时解耦的收益更明显，但也更容易撞上跨集群跳数上限。</p>\n\n<h3 id=\"alg-disagg-expert-parallel-sec-46\">四十六 · 与统一 EP 的对照：解耦换来了什么、失去了什么</h3>\n<p>统一 EP 的每层两次 All-to-All 是同步屏障，所有 GPU 必须等最慢的那条链路。分离式把专家池抽出为独立服务集群，注意力 GPU 只做路由与打包，dispatch 经 RDMA 按专家 ID 落到对应 GPU，combine 按原 token 索引回传并按路由权重加权合并。收益是可分别扩缩容：预填用大 EP 度数摊薄权重读取，解码用小 EP 度数降低跳数，$\\text{EP}_{\\text{opt}}$ 不再是一个全局常数而是两套配置。</p>\n<p>失去的是同步语义的简洁性。统一 EP 里一次 All-to-All 完成即全局可见；解耦后 token 跨集群往返引入额外网络跳数与序列化开销，且专家集群故障会阻塞所有注意力 GPU，缺乏重路由时整个服务停摆。因此选分离式的前置条件是：已有容错与重路由机制，且跨集群链路带宽足以让 $T_{\\text{comm}}$ 在目标 batch 下不超过 $T_{\\text{gemm}}$。判断方法很直接：用 $M_{\\text{disp}}$ 除以链路带宽得到单层通信下界，与实测分组 GEMM 时间比较，若前者在解码 batch 下已接近后者，解耦收益被抵消。</p>\n<p>具体例子：一个大规模 MoE 服务，预填 batch 使 $M_{\\text{disp}}$ 很大但 GEMM 同样大，大 EP 度数下每卡权重读取被摊薄到可容纳；解码 batch 小，若沿用同一 EP 度数，两次 All-to-All 的固定时延占比高，TPOT 被通信主导。此时把解码切到小 EP 度数并走独立专家集群，跳数下降，代价是专家集群需按解码峰值单独预留显存，预留不当会造成负载倾斜与显存浪费。</p>\n\n<h3 id=\"alg-disagg-expert-parallel-sec-47\">四十七 · 与路由侧算法的对照：丢弃、选择与块稀疏的取舍</h3>\n<p>路由侧三种形态改的是“进入 GEMM 的 token 集合形状”，与解耦改的是“token 走哪条路”。容量因子路由用容量上限截断，超出即丢弃，换来分组 GEMM 形状规整与显存预留可控；专家选择路由让专家主动选 token，缓解倾斜；无丢弃块稀疏分组 GEMM 用块稀疏元数据保住全部 token，代价是 kernel 复杂度与元数据开销。三者与分离式叠加时的关键交互是 $N_{\\text{tok}}$：丢弃会缩小有效 $N_{\\text{tok}}$，使 $M_{\\text{disp}}$ 下降、通信看似变便宜，但质量损失不可逆；块稀疏保住 $N_{\\text{tok}}$，$M_{\\text{disp}}$ 维持高位，跨集群带宽压力更大。</p>\n<p>决策规则：质量敏感且专家形状不规则时，选无丢弃块稀疏分组 GEMM，并接受更高的 dispatch 字节数，此时应把 EP 度数调大以摊薄权重读取、把通信压力摊到更多链路上；可容忍丢弃且负载倾斜严重时，容量因子路由更省显存与带宽，但要把丢弃率纳入 SLO 预算，不能只看吞吐。专家选择路由适合路由抖动导致的倾斜，它与解耦正交，可同时启用，但路由元数据会进入 $w_{\\text{route}}$ 项，抬高 $M_{\\text{disp}}$。</p>\n<p>代价对照：块稀疏元数据增加每层固定开销，在小 batch decode 下这部分开销占比上升；容量因子路由的显存预留按容量上限分配，解码低谷期形成闲置，与专家集群独立扩缩容的弹性目标冲突。具体例子：解码 batch 很小时，容量因子把每专家预留压到很小，GEMM 形状规整但大量专家空转；块稀疏则把稀疏块真正跳过，GEMM 有效利用率上升，代价是 dispatch 消息量不降。</p>\n\n<h3 id=\"alg-disagg-expert-parallel-sec-48\">四十八 · 与数值精度侧的对照：量化改变的是分母</h3>\n<p>NVFP4/FP8 微缩放量化把权重与激活的字节数压下来，直接改变 $T_{\\text{gemm}}$ 中的权重读取项与 $M_{\\text{disp}}$ 中的 $d_{\\text{model}}$ 有效字节。它与分离式的关系是“改变分母”：量化后 GEMM 变快，$T_{\\text{comm}}$ 在单层时间中的占比上升，解耦的边际收益变大，但也更快撞上跨集群跳数上限。反过来，若量化后 GEMM 已不是瓶颈，把专家池解耦出去只增加往返开销，不如留在统一 EP 内。</p>\n<p>决策上先算比值：量化前后 $T_{\\text{gemm}}$ 与 $T_{\\text{comm}}$ 的比例若发生翻转，说明瓶颈已从计算移到通信，此时应优先解耦并下调解码 EP 度数；若比例未翻转，量化融合大核单独使用即可，不必引入跨集群跳数。精度预算上，量化误差在专家层累积，与路由丢弃的质量损失叠加时需分开计量，不能把两者混为一个“质量下降”指标。代价：量化校准成本与精度敏感层的回退策略会占用工程预算，而解耦带来的容错与重路由机制同样占用预算，两者同时上马时要把运维复杂度计入容量规划。</p>\n<p>具体例子：权重带宽主导的 decode 场景，量化把权重读取字节数降下来，单卡可容纳更多专家，于是小 EP 度数即可覆盖全部专家，跳数进一步下降；这是量化与解耦同向增益的情形。反之，若某层精度敏感必须保留高精度权重，该层权重读取不降，解耦后跨集群搬运的字节数不变，收益仅来自跳数优化，需单独评估是否值得。</p>\n\n<h3 id=\"alg-disagg-expert-parallel-sec-49\">四十九 · 决策顺序与工程判断</h3>\n<p>给出可执行的判定顺序，避免在多个形态间反复摇摆。第一步测 $T_{\\text{gemm}}$ 与 $T_{\\text{comm}}$ 在预填与解码两种 batch 下的比值；第二步看两者比值是否分裂——分裂才考虑解耦，不分裂则留在统一 EP 并优先做量化或路由侧优化；第三步若解耦，按预填大 EP、解码小 EP 配置，并用 $M_{\\text{disp}}/\\text{BW}_{\\text{link}}$ 校验解码侧通信下界是否低于分组 GEMM 时间；第四步检查容错：专家集群故障是否会阻塞全部注意力 GPU，无重路由则不部署；第五步把路由侧与量化侧作为正交增益叠加，但每次叠加后重算比值，因为量化会抬高通信占比、丢弃会缩小有效 $N_{\\text{tok}}$。</p>\n<p>工程判断落在三个数字上：跨集群往返时延、单层分组 GEMM 时间、专家集群按解码峰值预留的显存。三者中任一越界，解耦就从收益变为负担。规模上限受跨集群网络跳数与序列化开销约束，小 batch decode 场景收益递减，这是选型的硬边界而非调参能解决的问题。最终选择应写成配置而非口号：预填 EP 度数、解码 EP 度数、路由形态、量化精度、容错重路由开关，五项一起定，缺一项就会在负载倾斜或故障时暴露。</p>\n\n<h3 id=\"alg-disagg-expert-parallel-sec-50\">五十 · 解耦 EP 的边界判定：与统一 EP、纯 PD 分离的三角取舍</h3>\n<p>把本方案放回同族算法坐标系里，它既不是统一 EP 的替代品，也不是 PD 分离的变体，而是沿“专家权重放在哪、通信走几跳”这一维度的第三种切法。统一 EP 的代价结构是每层两次 All-to-All，通信量与 $N_{\\text{tok}} \\times k \\times d_{\\text{model}}$ 同阶但只跨一次 NVLink 域；纯 PD 分离只拆预填与解码，专家仍与注意力同机，通信拓扑不变；本方案把专家池整体外移，换来预填/解码各自选 EP 度数的自由，代价是 token 多一次跨集群往返。判据不是“谁更先进”，而是把层时延公式拆开看哪一项占优：</p>\n<div class=\"formula\">$$T_{\\text{layer}}=T_{\\text{attn}}+\\frac{S_{\\text{token}}\\,N_{\\text{token}}}{\\text{BW}_{\\text{link}}}+T_{\\text{gemm}}+\\frac{S_{\\text{out}}\\,N_{\\text{token}}}{\\text{BW}_{\\text{link}}}$$</div>\n<p>统一 EP 下 $\\text{BW}_{\\text{link}}$ 是机内 NVLink，$T_{\\text{comm}}$ 小但 $T_{\\text{gemm}}$ 受 EP 度数牵制；解耦后 $\\text{BW}_{\\text{link}}$ 变为跨集群 RDMA，$T_{\\text{comm}}$ 抬升而 $T_{\\text{gemm}}$ 可按阶段独立调优。决策点因此落在“$T_{\\text{comm}}$ 的增量能否被 $T_{\\text{gemm}}$ 的下降抵消”。预填阶段 token 多、GEMM 占主导，大 EP 度数摊薄权重读取的收益远大于跨集群跳数开销，解耦明确占优；解码阶段 token 少、$T_{\\text{comm}}$ 与固定时延（序列化、建链、重路由查表）成为主项，此时应退回小 EP 度数甚至机内统一 EP。工程上可用一个粗略的比较式做门限判断：当 $N_{\\text{tok}} \\times k \\times (d_{\\text{model}}+w_{\\text{route}})/\\text{BW}_{\\text{rdma}}$ 超过分组 GEMM 的实测时延时，解耦在该 batch 上失效。</p>\n<table class=\"mini\"><thead><tr><th>场景条件</th><th>首选方案</th><th>失效信号</th></tr></thead><tbody><tr><td>长预填、专家层为独立瓶颈、集群可独立扩容</td><td>解耦 EP，预填用大 EP 度数</td><td>专家集群利用率长期低于注意力侧</td></tr><tr><td>短解码、小 batch、SLO 卡在 TPOT</td><td>统一 EP 或机内小 EP 度数</td><td>跨集群往返时延超过分组 GEMM</td></tr><tr><td>预填/解码通信需求差异大但集群规模有限</td><td>PD 分离 + 机内 EP，暂不解耦专家</td><td>专家权重读取成为预填瓶颈</td></tr><tr><td>专家集群故障域不可控</td><td>统一 EP 或带重路由的解耦</td><td>缺重路由时全服务停摆</td></tr></tbody></table>\n<p>还有两个容易被忽略的边界。其一是负载倾斜：预填与解码用不同 EP 度数时，专家集群的显存预留必须按两套并行度分别规划，若按单一度数预留，切换阶段会出现专家副本空置或热点专家排队，这部分浪费在容量规划里要单独计入。其二是故障域放大：解耦把专家集群变成所有注意力 GPU 的公共依赖，任何专家节点失联都会阻塞全部发起方，因此重路由机制不是可选优化而是准入条件——没有 token 级重派发能力，就不应上解耦。反过来，若服务形态是长预填加短解码的自回归、且专家层确实构成独立瓶颈，解耦 EP 的收益是结构性的，此时应优先投入跨集群 RDMA 带宽与序列化开销的压缩，而不是继续在统一 EP 里调 All-to-All 的重叠粒度。</p>\n<table class=\"mini\" data-fig=\"alg-quick\"><caption>速查：这一页回答的五件事</caption><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td>年份 · 方向</td><td>2025 · 分组GEMM与tcgen05</td></tr><tr><td>解决什么</td><td>传统专家并行把专家权重切分到所有 GPU，每层两次 All-to-All 同步，decode 时通信时延占比高；预填与…</td></tr><tr><td>一句话机制</td><td>把专家池从注意力层解耦为独立的专家服务集群，注意力 GPU 通过 All-to-All 把 token 发给专家集群，…</td></tr><tr><td>代价与失效</td><td>token 跨集群往返引入额外网络跳数与序列化开销，小 batch decode 时通信时延可能超过 GEMM；专家集群故障会阻塞所有注意…</td></tr><tr><td>后继</td><td></td></tr></tbody></table>\n<p class=\"paper-line\">本页对应：algorithms/alg-disagg-expert-parallel · 共 8 个片段</p>\n";break;}}})();
